/*************************************************************************
A general QP problem (a linear/quadratic target subject to a mix  of  box,
linear, quadratic and conic constraints).

  -- ALGLIB --
     Copyright 20.07.2021 by Bochkanov Sergey
*************************************************************************/
_qpxproblem_owner::_qpxproblem_owner()
{
    jmp_buf _break_jump;
    alglib_impl::ae_state _state;
    
    alglib_impl::ae_state_init(&_state);
    if( setjmp(_break_jump) )
    {
        if( p_struct!=NULL )
        {
            alglib_impl::_qpxproblem_destroy(p_struct);
            alglib_impl::ae_free(p_struct);
        }
        p_struct = NULL;
#if !defined(AE_NO_EXCEPTIONS)
        _ALGLIB_CPP_EXCEPTION(_state.error_msg);
#else
        _ALGLIB_SET_ERROR_FLAG(_state.error_msg);
        return;
#endif
    }
    alglib_impl::ae_state_set_break_jump(&_state, &_break_jump);
    p_struct = NULL;
    p_struct = (alglib_impl::qpxproblem*)alglib_impl::ae_malloc(sizeof(alglib_impl::qpxproblem), &_state);
    memset(p_struct, 0, sizeof(alglib_impl::qpxproblem));
    alglib_impl::_qpxproblem_init(p_struct, &_state, ae_false);
    ae_state_clear(&_state);
    is_attached = false;
}

_qpxproblem_owner::_qpxproblem_owner(alglib_impl::qpxproblem *attach_to)
{
    p_struct = attach_to;
    is_attached = true;
}

_qpxproblem_owner::_qpxproblem_owner(const _qpxproblem_owner &rhs)
{
    jmp_buf _break_jump;
    alglib_impl::ae_state _state;
    
    alglib_impl::ae_state_init(&_state);
    if( setjmp(_break_jump) )
    {
        if( p_struct!=NULL )
        {
            alglib_impl::_qpxproblem_destroy(p_struct);
            alglib_impl::ae_free(p_struct);
        }
        p_struct = NULL;
#if !defined(AE_NO_EXCEPTIONS)
        _ALGLIB_CPP_EXCEPTION(_state.error_msg);
#else
        _ALGLIB_SET_ERROR_FLAG(_state.error_msg);
        return;
#endif
    }
    alglib_impl::ae_state_set_break_jump(&_state, &_break_jump);
    p_struct = NULL;
    alglib_impl::ae_assert(rhs.p_struct!=NULL, "ALGLIB: qpxproblem copy constructor failure (source is not initialized)", &_state);
    p_struct = (alglib_impl::qpxproblem*)alglib_impl::ae_malloc(sizeof(alglib_impl::qpxproblem), &_state);
    memset(p_struct, 0, sizeof(alglib_impl::qpxproblem));
    alglib_impl::_qpxproblem_init_copy(p_struct, const_cast<alglib_impl::qpxproblem*>(rhs.p_struct), &_state, ae_false);
    ae_state_clear(&_state);
    is_attached = false;
}

_qpxproblem_owner& _qpxproblem_owner::operator=(const _qpxproblem_owner &rhs)
{
    if( this==&rhs )
        return *this;
    jmp_buf _break_jump;
    alglib_impl::ae_state _state;
    
    alglib_impl::ae_state_init(&_state);
    if( setjmp(_break_jump) )
    {
#if !defined(AE_NO_EXCEPTIONS)
        _ALGLIB_CPP_EXCEPTION(_state.error_msg);
#else
        _ALGLIB_SET_ERROR_FLAG(_state.error_msg);
        return *this;
#endif
    }
    alglib_impl::ae_state_set_break_jump(&_state, &_break_jump);
    alglib_impl::ae_assert(p_struct!=NULL, "ALGLIB: qpxproblem assignment constructor failure (destination is not initialized)", &_state);
    alglib_impl::ae_assert(rhs.p_struct!=NULL, "ALGLIB: qpxproblem assignment constructor failure (source is not initialized)", &_state);
    alglib_impl::ae_assert(!is_attached, "ALGLIB: qpxproblem assignment constructor failure (can not assign to the structure which is attached to something else)", &_state);
    alglib_impl::_qpxproblem_destroy(p_struct);
    memset(p_struct, 0, sizeof(alglib_impl::qpxproblem));
    alglib_impl::_qpxproblem_init_copy(p_struct, const_cast<alglib_impl::qpxproblem*>(rhs.p_struct), &_state, ae_false);
    ae_state_clear(&_state);
    return *this;
}

_qpxproblem_owner::~_qpxproblem_owner()
{
    if( p_struct!=NULL && !is_attached )
    {
        alglib_impl::_qpxproblem_destroy(p_struct);
        ae_free(p_struct);
    }
}

alglib_impl::qpxproblem* _qpxproblem_owner::c_ptr()
{
    return p_struct;
}

const alglib_impl::qpxproblem* _qpxproblem_owner::c_ptr() const
{
    return p_struct;
}
qpxproblem::qpxproblem() : _qpxproblem_owner() 
{
}

qpxproblem::qpxproblem(alglib_impl::qpxproblem *attach_to):_qpxproblem_owner(attach_to) 
{
}

qpxproblem::qpxproblem(const qpxproblem &rhs):_qpxproblem_owner(rhs) 
{
}

qpxproblem& qpxproblem::operator=(const qpxproblem &rhs)
{
    if( this==&rhs )
        return *this;
    _qpxproblem_owner::operator=(rhs);
    return *this;
}

qpxproblem::~qpxproblem()
{
}




