/*************************************************************************
Get quadratic term, returns zero matrix if no quadratic term is present

  -- ALGLIB --
     Copyright 25.08.2024 by Bochkanov Sergey
*************************************************************************/
void qpxproblemgetquadraticterm(qpxproblem* p,
     sparsematrix* q,
     ae_bool* isupper,
     ae_state *_state)
{

    _sparsematrix_clear(q);
    *isupper = ae_false;

    if( !p->hasq )
    {
        q->matrixtype = 1;
        q->m = p->n;
        q->n = p->n;
        q->ninitialized = 0;
        isetallocv(p->n, 0, &q->didx, _state);
        isetallocv(p->n, 0, &q->uidx, _state);
        isetallocv(p->n+1, 0, &q->ridx, _state);
        *isupper = ae_false;
        return;
    }
    *isupper = p->isupperq;
    sparsecopybuf(&p->q, q, _state);
}


/*************************************************************************
Returns False if no quadratic term was specified, or quadratic term is
numerically zero.

  -- ALGLIB --
     Copyright 25.08.2024 by Bochkanov Sergey
*************************************************************************/
ae_bool qpxproblemhasquadraticterm(qpxproblem* p, ae_state *_state)
{
    ae_bool result;


    if( !p->hasq )
    {
        result = ae_false;
        return result;
    }
    result = p->q.ridx.ptr.p_int[p->n]>0;
    return result;
}


