/*************************************************************************
Get IDX-th two-sided quadratic constraint, same format as minqpaddqc2(),
except for the fact that it always returns isUpper=False, even if the
original matrix was an upper triangular one.

NOTE: this function is not optimized for big matrices. Whilst still having
      O(max(N,Nonzeros)) running time, it may  be  somewhat  slow  due  to
      dynamic structures being used internally.
      

  -- ALGLIB --
     Copyright 19.08.2024 by Bochkanov Sergey
*************************************************************************/
void qpxproblemgetqc2i(qpxproblem* p,
     ae_int_t idx,
     sparsematrix* q,
     ae_bool* isupper,
     /* Real    */ ae_vector* b,
     double* cl,
     double* cu,
     ae_bool* applyorigin,
     ae_state *_state)
{
    ae_frame _frame_block;
    xquadraticconstraint *qci;
    ae_smart_ptr _qci;
    ae_int_t i;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t jj;
    ae_int_t j;
    double v;

    ae_frame_make(_state, &_frame_block);
    memset(&_qci, 0, sizeof(_qci));
    _sparsematrix_clear(q);
    *isupper = ae_false;
    ae_vector_clear(b);
    *cl = 0.0;
    *cu = 0.0;
    *applyorigin = ae_false;
    ae_smart_ptr_init(&_qci, (void**)&qci, ae_false, _state, ae_true);

    ae_assert(idx>=0&&idx<p->mqc, "QPXProblemGetQC2i: Idx is outside of [0,MQC) range", _state);
    ae_obj_array_get(&p->qc.constraints, idx, &_qci, _state);
    if( qci->nvars==0 )
    {
        q->matrixtype = 1;
        q->m = p->n;
        q->n = p->n;
        q->ninitialized = 0;
        isetallocv(p->n, 0, &q->didx, _state);
        isetallocv(p->n, 0, &q->uidx, _state);
        isetallocv(p->n+1, 0, &q->ridx, _state);
        *isupper = ae_false;
        rsetallocv(p->n, 0.0, b, _state);
        *cl = qci->cl;
        *cu = qci->cu;
        *applyorigin = qci->applyorigin;
        ae_frame_leave(_state);
        return;
    }
    sparsecreatebuf(p->n, p->n, qci->lowerq.ridx.ptr.p_int[qci->nvars], q, _state);
    for(i=0; i<=qci->nvars-1; i++)
    {
        j0 = qci->lowerq.ridx.ptr.p_int[i];
        j1 = qci->lowerq.ridx.ptr.p_int[i+1]-1;
        for(jj=j0; jj<=j1; jj++)
        {
            j = qci->lowerq.idx.ptr.p_int[jj];
            v = qci->lowerq.vals.ptr.p_double[jj];
            sparseset(q, qci->varidx.ptr.p_int[i], qci->varidx.ptr.p_int[j], v, _state);
        }
    }
    sparseconverttocrs(q, _state);
    *isupper = ae_false;
    rsetallocv(p->n, 0.0, b, _state);
    for(i=0; i<=qci->nvars-1; i++)
    {
        b->ptr.p_double[qci->varidx.ptr.p_int[i]] = qci->b.ptr.p_double[i];
    }
    *cl = qci->cl;
    *cu = qci->cu;
    *applyorigin = qci->applyorigin;
    ae_frame_leave(_state);
}


/*************************************************************************
Copies quadratic constraints structure, target structure is cleared,
previously allocated memory is ignored.
*************************************************************************/
void xqccopy(xquadraticconstraints* src,
     xquadraticconstraints* dst,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t i;
    ae_int_t m;
    xquadraticconstraint *c;
    ae_smart_ptr _c;
    xquadraticconstraint *c1;
    ae_smart_ptr _c1;

    ae_frame_make(_state, &_frame_block);
    memset(&_c, 0, sizeof(_c));
    memset(&_c1, 0, sizeof(_c1));
    ae_smart_ptr_init(&_c, (void**)&c, ae_false, _state, ae_true);
    ae_smart_ptr_init(&_c1, (void**)&c1, ae_false, _state, ae_true);

    dst->n = src->n;
    m = ae_obj_array_get_length(&src->constraints);
    ae_obj_array_clear(&dst->constraints);
    for(i=0; i<=m-1; i++)
    {
        ae_obj_array_get(&src->constraints, i, &_c, _state);
        c1 = (xquadraticconstraint*)ae_malloc(sizeof(xquadraticconstraint), _state); /* note: using c1 as a temporary prior to assigning its value to _c1 */
        memset(c1, 0, sizeof(xquadraticconstraint));
        _xquadraticconstraint_init(c1, _state, ae_false);
        ae_smart_ptr_assign(&_c1, c1, ae_true, ae_true, (ae_int_t)sizeof(xquadraticconstraint), _xquadraticconstraint_init_copy, _xquadraticconstraint_destroy);
        c1->nvars = c->nvars;
        c1->cl = c->cl;
        c1->cu = c->cu;
        c1->applyorigin = c->applyorigin;
        if( c->nvars>0 )
        {
            icopyallocv(c->nvars, &c->varidx, &c1->varidx, _state);
            rcopyallocv(c->nvars, &c->b, &c1->b, _state);
            sparsecopybuf(&c->lowerq, &c1->lowerq, _state);
        }
        ae_obj_array_append_transfer(&dst->constraints, &_c1, _state);
    }
    ae_frame_leave(_state);
}


/*************************************************************************
Get constraints count
*************************************************************************/
ae_int_t xqcgetcount(const xquadraticconstraints* xqc, ae_state *_state)
{
    ae_int_t result;


    result = ae_obj_array_get_length(&xqc->constraints);
    return result;
}


void _xlinearconstraints_init(void* _p, ae_state *_state, ae_bool make_automatic)
{
    xlinearconstraints *p = (xlinearconstraints*)_p;
    ae_touch_ptr((void*)p);
    ae_matrix_init(&p->densec, 0, 0, DT_REAL, _state, make_automatic);
    _sparsematrix_init(&p->sparsec, _state, make_automatic);
    ae_vector_init(&p->dcl, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->dcu, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->scl, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->scu, 0, DT_REAL, _state, make_automatic);
    ae_matrix_init(&p->cleic, 0, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->lcsrcidx, 0, DT_INT, _state, make_automatic);
    ae_vector_init(&p->lcsrcmult, 0, DT_REAL, _state, make_automatic);
    _sparsematrix_init(&p->effsparsea, _state, make_automatic);
    ae_vector_init(&p->effal, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->effau, 0, DT_REAL, _state, make_automatic);
    _sparsematrix_init(&p->tmps, _state, make_automatic);
}


void _xlinearconstraints_init_copy(void* _dst, const void* _src, ae_state *_state, ae_bool make_automatic)
{
    xlinearconstraints       *dst = (xlinearconstraints*)_dst;
    const xlinearconstraints *src = (const xlinearconstraints*)_src;
    dst->n = src->n;
    dst->ndense = src->ndense;
    dst->nsparse = src->nsparse;
    ae_matrix_init_copy(&dst->densec, &src->densec, _state, make_automatic);
    _sparsematrix_init_copy(&dst->sparsec, &src->sparsec, _state, make_automatic);
    ae_vector_init_copy(&dst->dcl, &src->dcl, _state, make_automatic);
    ae_vector_init_copy(&dst->dcu, &src->dcu, _state, make_automatic);
    ae_vector_init_copy(&dst->scl, &src->scl, _state, make_automatic);
    ae_vector_init_copy(&dst->scu, &src->scu, _state, make_automatic);
    dst->nec = src->nec;
    dst->nic = src->nic;
    ae_matrix_init_copy(&dst->cleic, &src->cleic, _state, make_automatic);
    ae_vector_init_copy(&dst->lcsrcidx, &src->lcsrcidx, _state, make_automatic);
    ae_vector_init_copy(&dst->lcsrcmult, &src->lcsrcmult, _state, make_automatic);
    _sparsematrix_init_copy(&dst->effsparsea, &src->effsparsea, _state, make_automatic);
    ae_vector_init_copy(&dst->effal, &src->effal, _state, make_automatic);
    ae_vector_init_copy(&dst->effau, &src->effau, _state, make_automatic);
    _sparsematrix_init_copy(&dst->tmps, &src->tmps, _state, make_automatic);
}


void _xlinearconstraints_clear(void* _p)
{
    xlinearconstraints *p = (xlinearconstraints*)_p;
    ae_touch_ptr((void*)p);
    ae_matrix_clear(&p->densec);
    _sparsematrix_clear(&p->sparsec);
    ae_vector_clear(&p->dcl);
    ae_vector_clear(&p->dcu);
    ae_vector_clear(&p->scl);
    ae_vector_clear(&p->scu);
    ae_matrix_clear(&p->cleic);
    ae_vector_clear(&p->lcsrcidx);
    ae_vector_clear(&p->lcsrcmult);
    _sparsematrix_clear(&p->effsparsea);
    ae_vector_clear(&p->effal);
    ae_vector_clear(&p->effau);
    _sparsematrix_clear(&p->tmps);
}


void _xlinearconstraints_destroy(void* _p)
{
    xlinearconstraints *p = (xlinearconstraints*)_p;
    ae_touch_ptr((void*)p);
    ae_matrix_destroy(&p->densec);
    _sparsematrix_destroy(&p->sparsec);
    ae_vector_destroy(&p->dcl);
    ae_vector_destroy(&p->dcu);
    ae_vector_destroy(&p->scl);
    ae_vector_destroy(&p->scu);
    ae_matrix_destroy(&p->cleic);
    ae_vector_destroy(&p->lcsrcidx);
    ae_vector_destroy(&p->lcsrcmult);
    _sparsematrix_destroy(&p->effsparsea);
    ae_vector_destroy(&p->effal);
    ae_vector_destroy(&p->effau);
    _sparsematrix_destroy(&p->tmps);
}


void _lptestproblem_init(void* _p, ae_state *_state, ae_bool make_automatic)
{
    lptestproblem *p = (lptestproblem*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_init(&p->s, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->c, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->bndl, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->bndu, 0, DT_REAL, _state, make_automatic);
    _sparsematrix_init(&p->a, _state, make_automatic);
    ae_vector_init(&p->al, 0, DT_REAL, _state, make_automatic);
    ae_vector_init(&p->au, 0, DT_REAL, _state, make_automatic);
}


void _lptestproblem_init_copy(void* _dst, const void* _src, ae_state *_state, ae_bool make_automatic)
{
    lptestproblem       *dst = (lptestproblem*)_dst;
    const lptestproblem *src = (const lptestproblem*)_src;
    dst->n = src->n;
    dst->hasknowntarget = src->hasknowntarget;
    dst->targetf = src->targetf;
    ae_vector_init_copy(&dst->s, &src->s, _state, make_automatic);
    ae_vector_init_copy(&dst->c, &src->c, _state, make_automatic);
    ae_vector_init_copy(&dst->bndl, &src->bndl, _state, make_automatic);
    ae_vector_init_copy(&dst->bndu, &src->bndu, _state, make_automatic);
    dst->m = src->m;
    _sparsematrix_init_copy(&dst->a, &src->a, _state, make_automatic);
    ae_vector_init_copy(&dst->al, &src->al, _state, make_automatic);
    ae_vector_init_copy(&dst->au, &src->au, _state, make_automatic);
}


void _lptestproblem_clear(void* _p)
{
    lptestproblem *p = (lptestproblem*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_clear(&p->s);
    ae_vector_clear(&p->c);
    ae_vector_clear(&p->bndl);
    ae_vector_clear(&p->bndu);
    _sparsematrix_clear(&p->a);
    ae_vector_clear(&p->al);
    ae_vector_clear(&p->au);
}


void _lptestproblem_destroy(void* _p)
{
    lptestproblem *p = (lptestproblem*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_destroy(&p->s);
    ae_vector_destroy(&p->c);
    ae_vector_destroy(&p->bndl);
    ae_vector_destroy(&p->bndu);
    _sparsematrix_destroy(&p->a);
    ae_vector_destroy(&p->al);
    ae_vector_destroy(&p->au);
}


