/*************************************************************************
Creates a single-objective test problem from the METAHEURISTIC-U1 collection

INPUT PARAMETERS:
    ProblemIdx      -   a value from [0,MOTFGetMetaheuristicU1Size)
    IsRotated       -   if True, a random rotation is applied to variables
    RS              -   RNG, used for random rotations

  -- ALGLIB --
     Copyright 04.03.2023 by Bochkanov Sergey
*************************************************************************/
void motfcreatemetaheuristicu1(ae_int_t problemidx,
     ae_bool isrotated,
     hqrndstate* rs,
     multiobjectivetestfunction* problem,
     ae_state *_state)
{
    ae_bool processed;
    ae_int_t i;
    ae_int_t j;

    _multiobjectivetestfunction_clear(problem);

    
    /*
     * Set problem metrics
     */
    problem->problemtype = 1;
    problem->problemsubtype = problemidx;
    problem->isrotated = isrotated;
    problem->m = 1;
    problem->nlinear = 0;
    problem->nnonlinear = 0;
    ae_matrix_set_length(&problem->x0, 0, 0, _state);
    problem->k0 = 0;
    problem->ksol = 0;
    ae_matrix_set_length(&problem->xsol, 0, 0, _state);
    ae_matrix_set_length(&problem->fsol, 0, 0, _state);
    ae_vector_set_length(&problem->lagmultbc, 0, _state);
    ae_vector_set_length(&problem->lagmultlc, 0, _state);
    ae_vector_set_length(&problem->lagmultnlc, 0, _state);
    
    /*
     * Handle various problems from the collection
     */
    processed = ae_false;
    if( problemidx==0 )
    {
        
        /*
         * f_sp = sum(x^2)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-100), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(100), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==1 )
    {
        
        /*
         * f_sch = sum(|x|) + prod(|x|)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-10), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(10), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==2 )
    {
        
        /*
         * f_schDS
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-100), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(100), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==3 )
    {
        
        /*
         * f_sch
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-100), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(100), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==4 )
    {
        
        /*
         * f_ros
         */
        problem->n = 3;
        rsetallocv(problem->n, (double)(-30), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(30), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==5 )
    {
        
        /*
         * f = |x|^2 / (1+|x|^2)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-30), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(30), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==6 )
    {
        
        /*
         * f = |x| / (1+|x|)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-30), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(30), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==7 )
    {
        
        /*
         * f = |x| + |x|^2
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-30), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(30), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==8 )
    {
        
        /*
         * f_sp = sum(I*x^2)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-100), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(100), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==9 )
    {
        
        /*
         * f_sp = sum(I*|x|)
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-100), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(100), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    if( problemidx==10 )
    {
        
        /*
         * Brown function
         */
        problem->n = 30;
        rsetallocv(problem->n, (double)(-1), &problem->bndl, _state);
        rsetallocv(problem->n, (double)(4), &problem->bndu, _state);
        problem->ksol = 1;
        rsetallocm(1, problem->n, 0.0, &problem->xsol, _state);
        rsetallocm(1, 1, 0.0, &problem->fsol, _state);
        rsetallocv(problem->n, 0.0, &problem->lagmultbc, _state);
        processed = ae_true;
    }
    ae_assert(processed, "MOTFCreateMetaheuristicU1: incorrect ProblemIdx", _state);
    
    /*
     * Generate random rotation
     */
    if( isrotated )
    {
        hqrndnormalm(rs, problem->n, problem->n, &problem->rotq, _state);
        for(i=0; i<=problem->n-1; i++)
        {
            rmulr(problem->n, (double)1/coalesce(ae_sqrt(rdotrr(problem->n, &problem->rotq, i, &problem->rotq, i, _state), _state), (double)(1), _state), &problem->rotq, i, _state);
            for(j=i+1; j<=problem->n-1; j++)
            {
                raddrr(problem->n, -rdotrr(problem->n, &problem->rotq, i, &problem->rotq, j, _state), &problem->rotq, i, &problem->rotq, j, _state);
            }
        }
    }
}


