        problem->x0.ptr.pp_double[0][2] = (double)(-3);
        problem->x0.ptr.pp_double[0][3] = (double)(4);
        problem->x0.ptr.pp_double[0][4] = (double)(-5);
        problem->x0.ptr.pp_double[0][5] = (double)(6);
        problem->x0.ptr.pp_double[0][6] = (double)(-7);
