/*************************************************************************
Get recommended initial value for mu.

  -- ALGLIB --
     Copyright 01.02.2025 by Bochkanov Sergey
*************************************************************************/
double gipm3getinitprimdual(ae_state *_state)
{
    double result;


    result = gipm3_initmu;
    return result;
}


/*************************************************************************
Initialize GIPM structure

    TraceLevel              trace level:
                            * 0 for no trace
                            * 1 for laconic
                            * 2 for normal

  -- ALGLIB --
     Copyright 01.02.2025 by Bochkanov Sergey
*************************************************************************/
void gipm3initbuf(/* Real    */ const ae_vector* x0,
     ae_int_t n,
     double eps,
     ae_int_t maxits,
     ae_int_t tracelevel,
     ae_bool probeonfailure,
     ae_bool analyzestep,
     gipm3state* state,
     ae_state *_state)
{


    state->n = n;
    state->meq = 0;
    state->mi = 0;
    state->mh = 0;
    state->mxx = 0;
    state->primalbound = _state->v_posinf;
    state->dualbound = _state->v_neginf;
    state->eshasintmask = ae_false;
    state->esdualbound = _state->v_neginf;
    state->esprimbound = _state->v_posinf;
    state->esminits = 0;
    state->estol = 1.0E-6;
    bsetallocv(state->n, ae_false, &state->esintmask, _state);
    gipm3setprofilequasinewton(state, _state);
    
    /*
     * Save initial point for further processing
     */
    rcopyallocv(n, x0, &state->x0, _state);
    
    /*
     * Prepare RCOMM-V2 protocol
     */
    ae_vector_set_length(&state->rstate.ia, 4+1, _state);
    ae_vector_set_length(&state->rstate.ba, 1+1, _state);
    ae_vector_set_length(&state->rstate.ra, 16+1, _state);
    state->rstate.stage = -1;
    _rcommstate_clear_handler(&state->rstate);
    
    /*
     * Initial penalty to enforce bounded level sets
     */
    rsetallocv(n, 0.0, &state->pg, _state);
    
    /*
     * Stopping criteria and settings
     */
    ae_assert(ae_fp_greater_eq(eps,(double)(0)), "GIPM3: integrity check 554904 failed", _state);
    state->eps = coalesce(eps, (double)10*ae_sqrt(ae_machineepsilon, _state), _state);
    state->maxits = maxits;
    
    /*
     * Report fields
     */
    state->repnfev = 0;
    state->repnfact = 0;
    state->repnllsfact = 0;
    state->repterminationtype = 0;
    state->repiterationscount = 0;
    state->repearlyerrorestimate = (double)(0);
    state->repsclerr = (double)(0);
    
    /*
     * Trace status
     */
    state->dotracelaconic = tracelevel==1;
    state->dotrace = tracelevel>=2;
    state->doanytrace = state->dotrace||state->dotracelaconic;
    state->dodetailedtrace = tracelevel>=3;
    state->doprobeonfailure = tracelevel>=2&&probeonfailure;
    state->doanalyzestep = tracelevel>=2&&analyzestep;
}


/*************************************************************************
Set profile for a quasi-Newton version of the step (linear convergence)

  -- ALGLIB --
     Copyright 01.02.2025 by Bochkanov Sergey
*************************************************************************/
void gipm3setprofilequasinewton(gipm3state* state, ae_state *_state)
{


    state->sendqnupdates = ae_true;
    state->sendqnupdatesonfailedstep = ae_true;
    state->refactorizeafterqnupdate = ae_true;
    state->longsteps = ae_true;
    state->maxnewtontrustratio = (double)(50);
    state->muepsfactor = (double)(20);
    state->dualerrwgt = 10.0;
    state->mudecaylinear = 0.2;
    state->mudecaypower = 1.0;
    state->smalltrustrad = 0.01*ae_sqrt(ae_machineepsilon, _state);
    state->maxcheckpointstagnationits = 100;
}


void gipm3setconstr(gipm3state* state,
     /* Real    */ const ae_vector* ceq,
     ae_int_t meq,
     /* Real    */ const ae_vector* ci,
     ae_int_t mi,
     /* Real    */ const ae_vector* ch,
     /* Boolean */ const ae_vector* chislinear,
     ae_int_t mh,
     ae_state *_state)
{
    ae_int_t i;


    state->meq = meq;
    state->mi = mi;
    state->mh = mh;
    rcopyallocv(meq, ceq, &state->rhseq, _state);
    rcopyallocv(mi, ci, &state->rhsi, _state);
    rcopyallocv(mh, ch, &state->rhsh, _state);
    rsetallocv(mh, gipm3_defaultfractohard, &state->fractohard, _state);
    for(i=0; i<=mh-1; i++)
    {
        if( chislinear->ptr.p_bool[i] )
        {
            state->fractohard.ptr.p_double[i] = gipm3_fractobnd;
        }
    }
}


/*************************************************************************
This function allows to set optional primal bound for  the  algorithm.  If
a solver determines that it converges to a value  well  above  the  primal
bound, it will terminate prematurely with the Rep.TerminationType=6

Presently, only nonlinear IPM method supports primal bounds.

INPUT PARAMETERS:
    State   -   structure
    Bnd     -   primal bound, finite number or +INF (if no bound)

  -- ALGLIB --
     Copyright 02.02.2026 by Bochkanov Sergey
*************************************************************************/
void gipm3setprimalbound(gipm3state* state, double bnd, ae_state *_state)
{


    ae_assert(ae_isfinite(bnd, _state)||ae_isposinf(bnd, _state), "GIPM3SetPrimalBound: Bnd is not finite or +INF", _state);
    state->primalbound = bnd;
}


/*************************************************************************
This function allows to set optional dual bound for the  algorithm.

INPUT PARAMETERS:
    State   -   structure
    Bnd     -   dual bound, finite number or -INF (if no bound)

  -- ALGLIB --
     Copyright 02.02.2026 by Bochkanov Sergey
*************************************************************************/
void gipm3setdualbound(gipm3state* state, double bnd, ae_state *_state)
{


    ae_assert(ae_isfinite(bnd, _state)||ae_isneginf(bnd, _state), "GIPM3SetDualBound: Bnd is not finite or +INF", _state);
    state->dualbound = bnd;
}


/*************************************************************************
This function allows to set optional early stopping on integer variables


  -- ALGLIB --
     Copyright 02.02.2026 by Bochkanov Sergey
*************************************************************************/
void gipm3setearlystopping(gipm3state* state,
     /* Boolean */ const ae_vector* intmask,
     double dualbound,
     double primbound,
     ae_int_t minearlyits,
     double etol,
     ae_state *_state)
{
    ae_int_t i;


    ae_assert(intmask->cnt>=state->n, "GIPM3SetEarlyStopping: Length(intMask)<N", _state);
    bcopyv(state->n, intmask, &state->esintmask, _state);
    state->eshasintmask = ae_false;
    for(i=0; i<=state->n-1; i++)
    {
        state->eshasintmask = state->eshasintmask||intmask->ptr.p_bool[i];
    }
    state->esdualbound = dualbound;
    state->esprimbound = primbound;
    state->esminits = minearlyits;
    state->estol = etol;
}


