lbl_1:
    rallocv(n, &state->replyprod, _state);
    rcopyvx(state->current.meq, &state->current.ze, 0, &state->querydata, 0, _state);
    rcopyvx(state->current.mi, &state->current.zi, 0, &state->querydata, state->current.meq, _state);
