        {
            continue;
        }
        if( state->constrbucket.ptr.p_int[state->mnlc+i]==2 )
        {
            igrowappendv(offs+1, &state->srceihidx, state->mnlc+i, _state);
            rgrowappendv(offs+1, &state->srceihscl, rcase2(ae_isfinite(state->lcbndl.ptr.p_double[i], _state), 1.0, -1.0, _state), _state);
            rgrowappendv(offs+1, &state->srceihsft, 0.0, _state);
            rgrowappendv(state->mtotalh+1, &state->ch, rcase2(ae_isfinite(state->lcbndl.ptr.p_double[i], _state), state->lcbndl.ptr.p_double[i], -state->lcbndu.ptr.p_double[i], _state), _state);
            bgrowappendv(state->mtotalh+1, &state->chislinear, ae_true, _state);
            rgrowappendv(1+offs+1, &state->wrkfscales, 1.0, _state);
            state->mtotalh = state->mtotalh+1;
            offs = offs+1;
            continue;
        }
