/*************************************************************************
Initializes empty dynamic CRS matrix with either M or N equal to zero.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsinitempty(dynamiccrs* r,
     ae_int_t n,
     ae_int_t m,
     ae_state *_state)
{


    ae_assert(n*m==0, "DynCRSInitEmpty: M*N<>0", _state);
    r->m = m;
    r->n = n;
    if( m>0 )
    {
        isetallocv(m, 0, &r->rowbegin, _state);
        isetallocv(m, 0, &r->rowend, _state);
    }
    r->maxallocated = 0;
}


/*************************************************************************
Copies dynamic CRS matrix

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrscopy(const dynamiccrs* src, dynamiccrs* dst, ae_state *_state)
{
    ae_int_t i;
    ae_int_t m;
    ae_int_t n;
    ae_int_t rowsize;


    m = src->m;
    n = src->n;
    dst->m = m;
    dst->n = n;
    dst->maxallocated = 0;
    iallocv(m, &dst->rowbegin, _state);
    iallocv(m, &dst->rowend, _state);
    for(i=0; i<=m-1; i++)
    {
        rowsize = src->rowend.ptr.p_int[i]-src->rowbegin.ptr.p_int[i];
        dst->rowbegin.ptr.p_int[i] = dst->maxallocated;
        dst->rowend.ptr.p_int[i] = dst->maxallocated+rowsize;
        dst->maxallocated = dst->rowend.ptr.p_int[i];
        igrowv(dst->rowend.ptr.p_int[i], &dst->idx, _state);
        rgrowv(dst->rowend.ptr.p_int[i], &dst->vals, _state);
        icopyvx(rowsize, &src->idx, src->rowbegin.ptr.p_int[i], &dst->idx, dst->rowbegin.ptr.p_int[i], _state);
        rcopyvx(rowsize, &src->vals, src->rowbegin.ptr.p_int[i], &dst->vals, dst->rowbegin.ptr.p_int[i], _state);
    }
}


/*************************************************************************
Copies DynCRS matrix with deletion of row/column at position DeletePos
(the matrix must be square), with 0<=DeletePos<N/M. Cols/rows at the
position DeletePos and past it are shifted to the left. If N=M=1, then an
empty matrix is correctly created.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
void dyncrscopydeleterowcol(const dynamiccrs* src,
     ae_int_t deletepos,
     dynamiccrs* dst,
     ae_state *_state)
{
    ae_int_t isrc;
    ae_int_t idst;
    ae_int_t m;
    ae_int_t n;
    ae_int_t maxrowsize;
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t j;


    m = src->m;
    n = src->n;
    ae_assert(m==n, "DynCRSCopyDeleteRowCol: non-square input matrix", _state);
    ae_assert(0<=deletepos&&deletepos<n, "DynCRSCopyDeleteRowCol: incorrect DeletePos", _state);
    dst->m = m-1;
    dst->n = n-1;
    dst->maxallocated = 0;
    iallocv(m-1, &dst->rowbegin, _state);
    iallocv(m-1, &dst->rowend, _state);
    idst = 0;
    for(isrc=0; isrc<=m-1; isrc++)
    {
        if( isrc!=deletepos )
        {
            maxrowsize = src->rowend.ptr.p_int[isrc]-src->rowbegin.ptr.p_int[isrc];
            dst->rowbegin.ptr.p_int[idst] = dst->maxallocated;
            igrowv(dst->maxallocated+maxrowsize, &dst->idx, _state);
            rgrowv(dst->maxallocated+maxrowsize, &dst->vals, _state);
            j0 = src->rowbegin.ptr.p_int[isrc];
            j1 = src->rowend.ptr.p_int[isrc]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                if( src->idx.ptr.p_int[jj]!=deletepos )
                {
                    j = src->idx.ptr.p_int[jj];
                    if( j>deletepos )
                    {
                        j = j-1;
                    }
                    dst->idx.ptr.p_int[dst->maxallocated] = j;
                    dst->vals.ptr.p_double[dst->maxallocated] = src->vals.ptr.p_double[jj];
                    dst->maxallocated = dst->maxallocated+1;
                }
            }
            dst->rowend.ptr.p_int[idst] = dst->maxallocated;
            idst = idst+1;
        }
    }
}


/*************************************************************************
Copies DynCRS matrix with deletion of rows/columns at positions in DeleteSet
(the matrix must be square). Cols/rows are shifted to the left. The matrix
must be a square one.

Correctly creates an empty matrix if all rows/cols are removed.

Buf must be a preallocated array, with at least Src.N elements.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
void dyncrscopydeleterowscols(const dynamiccrs* src,
     const niset* deleteset,
     dynamiccrs* dst,
     /* Integer */ ae_vector* buf,
     ae_state *_state)
{
    ae_int_t isrc;
    ae_int_t idst;
    ae_int_t m;
    ae_int_t n;
    ae_int_t maxrowsize;
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t j;


    m = src->m;
    n = src->n;
    ae_assert(m==n, "DynCRSCopyDeleteRowsCols: non-square input matrix", _state);
    ae_assert(buf->cnt>=n, "DynCRSCopyDeleteRowsCols: buf[] array is too short", _state);
    ae_assert(0<=deleteset->nstored&&deleteset->nstored<=n, "DynCRSCopyDeleteRowsCols: incorrect DeleteSet size", _state);
    for(j=0; j<=deleteset->nstored-1; j++)
    {
        ae_assert(deleteset->items.ptr.p_int[j]>=0&&deleteset->items.ptr.p_int[j]<n, "DynCRSCopyDeleteRowsCols: items in DeleteSet are outside of [0,N) range", _state);
    }
    idst = 0;
    for(j=0; j<=n-1; j++)
    {
        if( deleteset->locationof.ptr.p_int[j]<0 )
        {
            buf->ptr.p_int[j] = idst;
            idst = idst+1;
        }
        else
        {
            buf->ptr.p_int[j] = -999999;
        }
    }
    dst->m = m-deleteset->nstored;
    dst->n = n-deleteset->nstored;
    dst->maxallocated = 0;
    iallocv(dst->m, &dst->rowbegin, _state);
    iallocv(dst->m, &dst->rowend, _state);
    idst = 0;
    for(isrc=0; isrc<=m-1; isrc++)
    {
        if( deleteset->locationof.ptr.p_int[isrc]<0 )
        {
            maxrowsize = src->rowend.ptr.p_int[isrc]-src->rowbegin.ptr.p_int[isrc];
            dst->rowbegin.ptr.p_int[idst] = dst->maxallocated;
            igrowv(dst->maxallocated+maxrowsize, &dst->idx, _state);
            rgrowv(dst->maxallocated+maxrowsize, &dst->vals, _state);
            j0 = src->rowbegin.ptr.p_int[isrc];
            j1 = src->rowend.ptr.p_int[isrc]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                if( deleteset->locationof.ptr.p_int[src->idx.ptr.p_int[jj]]<0 )
                {
                    j = src->idx.ptr.p_int[jj];
                    j = buf->ptr.p_int[j];
                    dst->idx.ptr.p_int[dst->maxallocated] = j;
                    dst->vals.ptr.p_double[dst->maxallocated] = src->vals.ptr.p_double[jj];
                    dst->maxallocated = dst->maxallocated+1;
                }
            }
            dst->rowend.ptr.p_int[idst] = dst->maxallocated;
            idst = idst+1;
        }
    }
}


/*************************************************************************
Copies DynCRS matrix with insertion of zero row/column at position InsertPos
(the matrix must be square), with 0<=InsertPos<=N/M. Cols/rows at the
position InsertPos and past it are shifted to the right. If N=M=1, then an
empty matrix is correctly created.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
void dyncrscopyinsertrowcol(const dynamiccrs* src,
     ae_int_t insertpos,
     dynamiccrs* dst,
     ae_state *_state)
{
    ae_int_t isrc;
    ae_int_t idst;
    ae_int_t m;
    ae_int_t n;
    ae_int_t maxrowsize;
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t j;


    m = src->m;
    n = src->n;
    ae_assert(m==n, "DynCRSCopyInsertRowCol: non-square input matrix", _state);
    ae_assert(0<=insertpos&&insertpos<=n, "DynCRSCopyInsertRowCol: incorrect InsertPos", _state);
    dst->m = m+1;
    dst->n = n+1;
    dst->maxallocated = 0;
    iallocv(m+1, &dst->rowbegin, _state);
    iallocv(m+1, &dst->rowend, _state);
    idst = 0;
    for(isrc=0; isrc<=m; isrc++)
    {
        if( isrc==insertpos )
        {
            dst->rowbegin.ptr.p_int[idst] = dst->maxallocated;
            igrowv(dst->maxallocated+1, &dst->idx, _state);
            rgrowv(dst->maxallocated+1, &dst->vals, _state);
            dst->idx.ptr.p_int[dst->maxallocated] = idst;
            dst->vals.ptr.p_double[dst->maxallocated] = 0.0;
            dst->maxallocated = dst->maxallocated+1;
            dst->rowend.ptr.p_int[idst] = dst->maxallocated;
            idst = idst+1;
        }
        if( isrc<m )
        {
            maxrowsize = src->rowend.ptr.p_int[isrc]-src->rowbegin.ptr.p_int[isrc];
            dst->rowbegin.ptr.p_int[idst] = dst->maxallocated;
            igrowv(dst->maxallocated+maxrowsize, &dst->idx, _state);
            rgrowv(dst->maxallocated+maxrowsize, &dst->vals, _state);
            j0 = src->rowbegin.ptr.p_int[isrc];
            j1 = src->rowend.ptr.p_int[isrc]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                j = src->idx.ptr.p_int[jj];
                if( j>=insertpos )
                {
                    j = j+1;
                }
                dst->idx.ptr.p_int[dst->maxallocated] = j;
                dst->vals.ptr.p_double[dst->maxallocated] = src->vals.ptr.p_double[jj];
                dst->maxallocated = dst->maxallocated+1;
            }
            dst->rowend.ptr.p_int[idst] = dst->maxallocated;
            idst = idst+1;
        }
    }
}


/*************************************************************************
Initialize dynamic CRS matrix using SparseMatrix structure

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsinitfromsparsecrs(const sparsematrix* s,
     dynamiccrs* r,
     ae_state *_state)
{
    ae_int_t m;
    ae_int_t n;


    m = s->m;
    n = s->n;
    ae_assert(s->matrixtype==1, "DynCRSInitFromSparseCRS: S is not CRS matrix", _state);
    r->m = m;
    r->n = n;
    icopyallocv(s->ridx.ptr.p_int[m], &s->idx, &r->idx, _state);
    rcopyallocv(s->ridx.ptr.p_int[m], &s->vals, &r->vals, _state);
    iallocv(m, &r->rowbegin, _state);
    iallocv(m, &r->rowend, _state);
    icopyvx(m, &s->ridx, 0, &r->rowbegin, 0, _state);
    icopyvx(m, &s->ridx, 1, &r->rowend, 0, _state);
    r->maxallocated = r->rowend.ptr.p_int[m-1];
}


/*************************************************************************
Drops numerical zeros from the matrix

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsdropzeros(dynamiccrs* a, ae_state *_state)
{
    ae_int_t m;
    ae_int_t i;
    ae_int_t j;
    ae_int_t jj;
    ae_int_t offs;
    double v;


    m = a->m;
    for(i=0; i<=m-1; i++)
    {
        offs = a->rowbegin.ptr.p_int[i];
        for(jj=a->rowbegin.ptr.p_int[i]; jj<=a->rowend.ptr.p_int[i]-1; jj++)
        {
            j = a->idx.ptr.p_int[jj];
            v = a->vals.ptr.p_double[jj];
            if( v==(double)0 )
            {
                continue;
            }
            a->idx.ptr.p_int[offs] = j;
            a->vals.ptr.p_double[offs] = v;
            offs = offs+1;
        }
        a->rowend.ptr.p_int[i] = offs;
    }
}


/*************************************************************************
Drops offdiagonal numerical zeros from the matrix

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsdropoffdiagonalzeros(dynamiccrs* a, ae_state *_state)
{
    ae_int_t m;
    ae_int_t i;
    ae_int_t j;
    ae_int_t jj;
    ae_int_t offs;
    double v;


    m = a->m;
    for(i=0; i<=m-1; i++)
    {
        offs = a->rowbegin.ptr.p_int[i];
        for(jj=a->rowbegin.ptr.p_int[i]; jj<=a->rowend.ptr.p_int[i]-1; jj++)
        {
            j = a->idx.ptr.p_int[jj];
            v = a->vals.ptr.p_double[jj];
            if( j!=i&&v==(double)0 )
            {
                continue;
            }
            a->idx.ptr.p_int[offs] = j;
            a->vals.ptr.p_double[offs] = v;
            offs = offs+1;
        }
        a->rowend.ptr.p_int[i] = offs;
    }
}


/*************************************************************************
Removes rows

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsclearrow(dynamiccrs* a, ae_int_t rowidx, ae_state *_state)
{


    a->rowend.ptr.p_int[rowidx] = a->rowbegin.ptr.p_int[rowidx];
}


/*************************************************************************
Removes element from the row

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsremovefromrow(dynamiccrs* a,
     ae_int_t rowidx,
     ae_int_t j,
     ae_state *_state)
{
    ae_int_t ii;
    ae_int_t offs;


    offs = a->rowbegin.ptr.p_int[rowidx];
    for(ii=a->rowbegin.ptr.p_int[rowidx]; ii<=a->rowend.ptr.p_int[rowidx]-1; ii++)
    {
        if( a->idx.ptr.p_int[ii]!=j )
        {
            a->idx.ptr.p_int[offs] = a->idx.ptr.p_int[ii];
            a->vals.ptr.p_double[offs] = a->vals.ptr.p_double[ii];
            offs = offs+1;
        }
    }
    a->rowend.ptr.p_int[rowidx] = offs;
}


/*************************************************************************
Factors out element J from the row RowIdx by means of transformation

    X[J] = C0+C1*X[K].
    
Depending on context, can be used to factor out elements from individual
rows of a quadratic matrix H (in this case C0 can be zero because it does
not actually used), or to factor out elements from the linear constraints
matrix.

The function returns the value of new element A[RowIdx,K]. A zero can be
returned, e.g. if cancellation or nearly-cancellation has occurred.

When used to process linear constraints, it also returns a shift that should be applied to row bounds,
which is equal to C0*A[I,J]. Correctly handles the situation when factoring
an element out results in a cancellation: if CheckCancellation is True,
it removes canceled element from the row.

When no element J is present in the row RowIdx, does nothing and returns zero.


  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsfactoroutfromrow(dynamiccrs* a,
     ae_int_t rowidx,
     ae_int_t j,
     double c0,
     double c1,
     ae_int_t k,
     ae_bool checkcancellation,
     double* newval,
     double* shift,
     ae_state *_state)
{
    ae_int_t ii;
    ae_int_t pos0;
    ae_int_t pos1;
    ae_int_t i;
    ae_int_t i0;
    ae_int_t i1;
    double eps;
    double mx;
    double v;

    *newval = 0.0;
    *shift = 0.0;

    eps = (double)10*ae_machineepsilon;
    *newval = 0.0;
    *shift = 0.0;
    pos0 = a->rowend.ptr.p_int[rowidx];
    pos1 = a->rowend.ptr.p_int[rowidx];
    for(ii=a->rowbegin.ptr.p_int[rowidx]; ii<=a->rowend.ptr.p_int[rowidx]-1; ii++)
    {
        if( a->idx.ptr.p_int[ii]==j )
        {
            pos0 = ii;
        }
        if( a->idx.ptr.p_int[ii]==k )
        {
            pos1 = ii;
        }
    }
    if( pos0==a->rowend.ptr.p_int[rowidx] )
    {
        return;
    }
    *shift = a->vals.ptr.p_double[pos0]*c0;
    if( pos1!=a->rowend.ptr.p_int[rowidx] )
    {
        mx = ae_maxreal(ae_fabs(a->vals.ptr.p_double[pos0], _state), ae_fabs(a->vals.ptr.p_double[pos1], _state), _state);
        v = a->vals.ptr.p_double[pos1]+a->vals.ptr.p_double[pos0]*c1;
        a->vals.ptr.p_double[pos1] = v;
        *newval = v;
        dyncrsremovefromrow(a, rowidx, j, _state);
        if( checkcancellation&&ae_fp_less_eq(ae_fabs(v, _state),eps*mx) )
        {
            dyncrsremovefromrow(a, rowidx, k, _state);
            *newval = 0.0;
        }
    }
    else
    {
        v = a->vals.ptr.p_double[pos0]*c1;
        a->idx.ptr.p_int[pos0] = k;
        a->vals.ptr.p_double[pos0] = v;
        *newval = v;
        if( k>j )
        {
            i0 = pos0;
            i1 = a->rowend.ptr.p_int[rowidx]-1;
            while(i0<i1)
            {
                i = a->idx.ptr.p_int[i0+1];
                if( i>k )
                {
                    break;
                }
                a->idx.ptr.p_int[i0] = i;
                a->vals.ptr.p_double[i0] = a->vals.ptr.p_double[i0+1];
                a->idx.ptr.p_int[i0+1] = k;
                a->vals.ptr.p_double[i0+1] = v;
                i0 = i0+1;
            }
        }
        else
        {
            i0 = pos0;
            i1 = a->rowbegin.ptr.p_int[rowidx];
            while(i0>i1)
            {
                i = a->idx.ptr.p_int[i0-1];
                if( i<k )
                {
                    break;
                }
                a->idx.ptr.p_int[i0] = i;
                a->vals.ptr.p_double[i0] = a->vals.ptr.p_double[i0-1];
                a->idx.ptr.p_int[i0-1] = k;
                a->vals.ptr.p_double[i0-1] = v;
                i0 = i0-1;
            }
        }
    }
}


/*************************************************************************
Adds Row0 times C to Row1. If RetainDiagonal is True, never removes diagonal
elements from Row1 even if cancellation is present


  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
void dyncrsaddrowto(dynamiccrs* a,
     ae_int_t row0,
     double c,
     ae_int_t row1,
     ae_bool retaindiagonal,
     ae_bool checkcancellation,
     ae_state *_state)
{
    ae_int_t begin0;
    ae_int_t begin1;
    ae_int_t end0;
    ae_int_t end1;
    ae_int_t i0;
    ae_int_t i1;
    double v0;
    double v1;
    double mx;
    ae_int_t beginr;
    ae_int_t endr;
    double eps;


    eps = (double)10*ae_machineepsilon;
    if( ae_fp_eq(c,0.0) )
    {
        return;
    }
    begin0 = a->rowbegin.ptr.p_int[row0];
    begin1 = a->rowbegin.ptr.p_int[row1];
    end0 = a->rowend.ptr.p_int[row0];
    end1 = a->rowend.ptr.p_int[row1];
    if( begin0==end0 )
    {
        return;
    }
    igrowv(a->maxallocated+(end0-begin0)+(end1-begin1), &a->idx, _state);
    rgrowv(a->maxallocated+(end0-begin0)+(end1-begin1), &a->vals, _state);
    beginr = a->maxallocated;
    endr = beginr;
    while(begin0<end0&&begin1<end1)
    {
        i0 = a->idx.ptr.p_int[begin0];
        i1 = a->idx.ptr.p_int[begin1];
        if( i0<i1 )
        {
            a->idx.ptr.p_int[endr] = i0;
            a->vals.ptr.p_double[endr] = c*a->vals.ptr.p_double[begin0];
            endr = endr+1;
            begin0 = begin0+1;
            continue;
        }
        if( i1<i0 )
        {
            a->idx.ptr.p_int[endr] = i1;
            a->vals.ptr.p_double[endr] = a->vals.ptr.p_double[begin1];
            endr = endr+1;
            begin1 = begin1+1;
            continue;
        }
        v0 = a->vals.ptr.p_double[begin0];
        v1 = a->vals.ptr.p_double[begin1];
        if( checkcancellation )
        {
            mx = ae_maxreal(ae_fabs(v0, _state), ae_fabs(v1, _state), _state);
            if( (!retaindiagonal||i1!=row1)&&(ae_fp_eq(mx,(double)(0))||ae_fabs(c*v0+v1, _state)<=eps*mx) )
            {
                begin0 = begin0+1;
                begin1 = begin1+1;
                continue;
            }
        }
        a->idx.ptr.p_int[endr] = i1;
        a->vals.ptr.p_double[endr] = c*v0+v1;
        endr = endr+1;
        begin0 = begin0+1;
        begin1 = begin1+1;
    }
    while(begin0<end0)
    {
        a->idx.ptr.p_int[endr] = a->idx.ptr.p_int[begin0];
        a->vals.ptr.p_double[endr] = c*a->vals.ptr.p_double[begin0];
        endr = endr+1;
        begin0 = begin0+1;
    }
    while(begin1<end1)
    {
        a->idx.ptr.p_int[endr] = a->idx.ptr.p_int[begin1];
        a->vals.ptr.p_double[endr] = a->vals.ptr.p_double[begin1];
        endr = endr+1;
        begin1 = begin1+1;
    }
    a->maxallocated = endr;
    a->rowbegin.ptr.p_int[row1] = beginr;
    a->rowend.ptr.p_int[row1] = endr;
}


/*************************************************************************
Inserts sparse vector into the row, rewriting existing elements by new values.
If a new value is zero, the element (if exists) is removed from the target
row.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsinsertwithrewrite(dynamiccrs* a,
     ae_int_t tgtrow,
     /* Integer */ const ae_vector* idx,
     /* Real    */ const ae_vector* vals,
     ae_int_t cnt,
     ae_state *_state)
{
    ae_int_t begins;
    ae_int_t ends;
    ae_int_t begini;
    ae_int_t i0;
    ae_int_t i1;
    ae_int_t beginr;
    ae_int_t endr;


    if( cnt==0 )
    {
        return;
    }
    begins = a->rowbegin.ptr.p_int[tgtrow];
    ends = a->rowend.ptr.p_int[tgtrow];
    igrowv(a->maxallocated+(ends-begins)+cnt, &a->idx, _state);
    rgrowv(a->maxallocated+(ends-begins)+cnt, &a->vals, _state);
    beginr = a->maxallocated;
    endr = beginr;
    begini = 0;
    while(begins<ends&&begini<cnt)
    {
        i0 = a->idx.ptr.p_int[begins];
        i1 = idx->ptr.p_int[begini];
        if( i0<i1 )
        {
            a->idx.ptr.p_int[endr] = i0;
            a->vals.ptr.p_double[endr] = a->vals.ptr.p_double[begins];
            endr = endr+1;
            begins = begins+1;
            continue;
        }
        if( i1<i0 )
        {
            if( vals->ptr.p_double[begini]!=0.0 )
            {
                a->idx.ptr.p_int[endr] = i1;
                a->vals.ptr.p_double[endr] = vals->ptr.p_double[begini];
                endr = endr+1;
            }
            begini = begini+1;
            continue;
        }
        if( vals->ptr.p_double[begini]!=0.0 )
        {
            a->idx.ptr.p_int[endr] = i1;
            a->vals.ptr.p_double[endr] = vals->ptr.p_double[begini];
            endr = endr+1;
        }
        begins = begins+1;
        begini = begini+1;
    }
    while(begins<ends)
    {
        a->idx.ptr.p_int[endr] = a->idx.ptr.p_int[begins];
        a->vals.ptr.p_double[endr] = a->vals.ptr.p_double[begins];
        endr = endr+1;
        begins = begins+1;
    }
    while(begini<cnt)
    {
        if( vals->ptr.p_double[begini]!=0.0 )
        {
            a->idx.ptr.p_int[endr] = idx->ptr.p_int[begini];
            a->vals.ptr.p_double[endr] = vals->ptr.p_double[begini];
            endr = endr+1;
        }
        begini = begini+1;
    }
    a->maxallocated = endr;
    a->rowbegin.ptr.p_int[tgtrow] = beginr;
    a->rowend.ptr.p_int[tgtrow] = endr;
}


/*************************************************************************
Removes elements with indexes in the set from the row

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void dyncrsremovesetfromrow(dynamiccrs* a,
     ae_int_t rowidx,
     const niset* s,
     ae_state *_state)
{
    ae_int_t ii;
    ae_int_t offs;


    offs = a->rowbegin.ptr.p_int[rowidx];
    for(ii=a->rowbegin.ptr.p_int[rowidx]; ii<=a->rowend.ptr.p_int[rowidx]-1; ii++)
    {
        if( s->locationof.ptr.p_int[a->idx.ptr.p_int[ii]]<0 )
        {
            a->idx.ptr.p_int[offs] = a->idx.ptr.p_int[ii];
            a->vals.ptr.p_double[offs] = a->vals.ptr.p_double[ii];
            offs = offs+1;
        }
    }
    a->rowend.ptr.p_int[rowidx] = offs;
}


/*************************************************************************
Computes dot product of C[] elements from the set S with corresponding
elements from A[RowIdx], and removes these elements from A[RowIdx]

  -- ALGLIB --
     Copyright 01.03.2026 by Bochkanov Sergey
*************************************************************************/
double dyncrsdotremovesetfromrow(dynamiccrs* a,
     ae_int_t rowidx,
     /* Real    */ const ae_vector* c,
     const niset* s,
     ae_state *_state)
{
    ae_int_t ii;
    ae_int_t i0;
    ae_int_t i1;
    ae_int_t offs;
    ae_int_t j;
    double result;


    result = (double)(0);
    i0 = a->rowbegin.ptr.p_int[rowidx];
    i1 = a->rowend.ptr.p_int[rowidx]-1;
    offs = i0;
    for(ii=a->rowbegin.ptr.p_int[rowidx]; ii<=i1; ii++)
    {
        j = a->idx.ptr.p_int[ii];
        if( s->locationof.ptr.p_int[j]<0 )
        {
            a->idx.ptr.p_int[offs] = j;
            a->vals.ptr.p_double[offs] = a->vals.ptr.p_double[ii];
            offs = offs+1;
        }
        else
        {
            result = result+c->ptr.p_double[j]*a->vals.ptr.p_double[ii];
        }
    }
    a->rowend.ptr.p_int[rowidx] = offs;
    return result;
}


/*************************************************************************
Get element that it known to exist in the matrix. If it does not, the
function fails with an exception. O(log(row_size)) running time.


  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
double dyncrsgetexistingelement(dynamiccrs* a,
     ae_int_t i,
     ae_int_t j,
     ae_state *_state)
{
    ae_int_t k;
    double result;


    k = ibinarysearchlft(&a->idx, a->rowbegin.ptr.p_int[i], a->rowend.ptr.p_int[i], j, _state);
    ae_assert(k<a->rowend.ptr.p_int[i]&&a->idx.ptr.p_int[k]==j, "DynCRSGetExistingElement: element not found", _state);
    result = a->vals.ptr.p_double[k];
    return result;
}


/*************************************************************************
Get element, return zero for non-existent element.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
double dyncrsgetelementifexists(dynamiccrs* a,
     ae_int_t i,
     ae_int_t j,
     ae_state *_state)
{
    ae_int_t k;
    double result;


    k = ibinarysearchlft(&a->idx, a->rowbegin.ptr.p_int[i], a->rowend.ptr.p_int[i], j, _state);
    result = (double)(0);
    if( k<a->rowend.ptr.p_int[i]&&a->idx.ptr.p_int[k]==j )
    {
        result = a->vals.ptr.p_double[k];
    }
    return result;
}


/*************************************************************************
Sets an element that it known to exist in the matrix. If it does not, the
function fails with an exception. O(log(row_size)) running time.


  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
void dyncrssetexistingelement(dynamiccrs* a,
     ae_int_t i,
     ae_int_t j,
     double v,
     ae_state *_state)
{
    ae_int_t k;


    k = ibinarysearchlft(&a->idx, a->rowbegin.ptr.p_int[i], a->rowend.ptr.p_int[i], j, _state);
    ae_assert(k<a->rowend.ptr.p_int[i]&&a->idx.ptr.p_int[k]==j, "DynCRSSetExistingElement: element not found", _state);
    a->vals.ptr.p_double[k] = v;
}


/*************************************************************************
Gets nonzero count, has O(M) running time

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
ae_int_t dyncrscountnonzeros(const dynamiccrs* a, ae_state *_state)
{
    ae_int_t rowidx;
    ae_int_t result;


    result = 0;
    for(rowidx=0; rowidx<=a->m-1; rowidx++)
    {
        result = result+(a->rowend.ptr.p_int[rowidx]-a->rowbegin.ptr.p_int[rowidx]);
    }
    return result;
}


void _dynamiccrs_init(void* _p, ae_state *_state, ae_bool make_automatic)
{
    dynamiccrs *p = (dynamiccrs*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_init(&p->rowbegin, 0, DT_INT, _state, make_automatic);
    ae_vector_init(&p->rowend, 0, DT_INT, _state, make_automatic);
    ae_vector_init(&p->idx, 0, DT_INT, _state, make_automatic);
    ae_vector_init(&p->vals, 0, DT_REAL, _state, make_automatic);
}


void _dynamiccrs_init_copy(void* _dst, const void* _src, ae_state *_state, ae_bool make_automatic)
{
    dynamiccrs       *dst = (dynamiccrs*)_dst;
    const dynamiccrs *src = (const dynamiccrs*)_src;
    dst->m = src->m;
    dst->n = src->n;
    dst->maxallocated = src->maxallocated;
    ae_vector_init_copy(&dst->rowbegin, &src->rowbegin, _state, make_automatic);
    ae_vector_init_copy(&dst->rowend, &src->rowend, _state, make_automatic);
    ae_vector_init_copy(&dst->idx, &src->idx, _state, make_automatic);
    ae_vector_init_copy(&dst->vals, &src->vals, _state, make_automatic);
}


void _dynamiccrs_clear(void* _p)
{
    dynamiccrs *p = (dynamiccrs*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_clear(&p->rowbegin);
    ae_vector_clear(&p->rowend);
    ae_vector_clear(&p->idx);
    ae_vector_clear(&p->vals);
}


void _dynamiccrs_destroy(void* _p)
{
    dynamiccrs *p = (dynamiccrs*)_p;
    ae_touch_ptr((void*)p);
    ae_vector_destroy(&p->rowbegin);
    ae_vector_destroy(&p->rowend);
    ae_vector_destroy(&p->idx);
    ae_vector_destroy(&p->vals);
}


