    rcopyvr(n, &state->meritg, &state->samplegm, 0, _state);
    if( !state->xrep )
    {
        goto lbl_6;
    }
    ae_v_move(&state->x.ptr.p_double[0], 1, &state->xc.ptr.p_double[0], 1, ae_v_len(0,n-1));
    state->f = currentf0;
    minns_clearrequestfields(state, _state);
    state->xupdated = ae_true;
    state->rstateags.stage = 1;
    if( state->rstateags.rcomm2_handler!=NULL && state->rstateags.requesttype!=0 && state->rstateags.requesttype<=_ALGLIB_MAX_RCOMMV2_REQUEST )
        state->rstateags.rcomm2_handler(&state->rstateags, state->rstateags.handler_p0, state->rstateags.handler_p1, state->rstateags.handler_p2, state->rstateags.handler_p3, _state);
