    ae_assert(ae_false, "MinDF: unexpected solver type", _state);
    result = ae_false;
    return result;
    
    /*
     * Saving state
     */
lbl_rcomm:
    result = ae_true;
    state->rcommv2.ia.ptr.p_int[0] = i;
    state->rcommv2.ia.ptr.p_int[1] = n;
    state->rcommv2.ia.ptr.p_int[2] = originalrequest;
    state->rcommv2.ba.ptr.p_bool[0] = b;
