/*************************************************************************
No presolve, just user-supplied scaling + constraint and cost vector
normalization.

INPUT PARAMETERS:
    S           -   array[N], user-supplied scale vector, S[I]>0
    C           -   array[N], costs
    BndL        -   array[N], lower bounds (may contain -INF)
    BndU        -   array[N], upper bounds (may contain +INF)
    N           -   variable count, N>0
    SparseA     -   matrix[K,N], sparse constraints
    AL          -   array[K], lower constraint bounds (may contain -INF)
    AU          -   array[K], upper constraint bounds (may contain +INF)
    K           -   constraint count, K>=0
    Info        -   presolve info structure; temporaries allocated during
                    previous calls may be reused by this function.
                    
OUTPUT PARAMETERS:
    Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                    and   information   necessary   to   perform  backward
                    transformation.
                    Following fields can be accessed:
                    * ProblemStatus    which is:
                                       *  0 for successful transformation
                                       * -3 for infeasible problem
                                       * -4 for unbounded problem
                    
                    If Info.ProblemStatus=0, then the following fields can
                    be accessed:
                    * Info.NewN>0  for transformed problem size
                    * Info.NewM>=0 for transformed linear constraint count
                    * Info.NewMQC>=0 for transformed quadratic constraint count
                    * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                    * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
                    * for Info.NewMQC>0: Info.XQC
    
NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

  -- ALGLIB --
     Copyright 01.07.2020 by Bochkanov Sergey
*************************************************************************/
void presolvenonescaleuser(/* Real    */ const ae_vector* s,
     /* Real    */ const ae_vector* xorigin,
     /* Real    */ const ae_vector* c,
     /* Real    */ const ae_vector* bndl,
     /* Real    */ const ae_vector* bndu,
     const sparsematrix* sparseh,
     ae_bool isupper,
     ae_bool hash,
     ae_int_t n,
     const sparsematrix* sparsea,
     /* Real    */ const ae_vector* al,
     /* Real    */ const ae_vector* au,
     ae_int_t k,
     xquadraticconstraints* xqc,
     xconicconstraints* xcc,
     ae_bool dotrace,
     presolveinfo* info,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t i;
    xconicconstraint *cc;
    ae_smart_ptr _cc;

    ae_frame_make(_state, &_frame_block);
    memset(&_cc, 0, sizeof(_cc));
    ae_smart_ptr_init(&_cc, (void**)&cc, ae_false, _state, ae_true);

    
    /*
     * Integrity checks
     */
    ae_assert(bndl->cnt>=n, "PresolveNoneScaleUser: Length(BndL)<N", _state);
    ae_assert(bndu->cnt>=n, "PresolveNoneScaleUser: Length(BndU)<N", _state);
    ae_assert(s->cnt>=n, "PresolveNoneScaleUser: Length(S)<N", _state);
    ae_assert(isfinitevector(s, n, _state), "PresolveNoneScaleUser: S contains infinite or NaN elements", _state);
    ae_assert(c->cnt>=n, "PresolveNoneScaleUser: Length(C)<N", _state);
    ae_assert(isfinitevector(c, n, _state), "PresolveNoneScaleUser: C contains infinite or NaN elements", _state);
    ae_assert(k>=0, "PresolveNoneScaleUser: K<0", _state);
    ae_assert(k==0||sparseiscrs(sparsea, _state), "PresolveNoneScaleUser: A is not CRS", _state);
    ae_assert(k==0||sparsea->m==k, "PresolveNoneScaleUser: rows(A)<>K", _state);
    ae_assert(k==0||sparsea->n==n, "PresolveNoneScaleUser: cols(A)<>N", _state);
    ae_assert(!hash||sparseiscrs(sparseh, _state), "PresolveNoneScaleUser: A is not CRS", _state);
    
    /*
     * Initial check for constraint feasibility and canonicity
     */
    for(i=0; i<=n-1; i++)
    {
        if( (ae_isfinite(bndl->ptr.p_double[i], _state)&&ae_isfinite(bndu->ptr.p_double[i], _state))&&ae_fp_greater(bndl->ptr.p_double[i],bndu->ptr.p_double[i]) )
        {
            if( dotrace )
            {
                ae_trace("> variable %0d is found to have infeasible box constraints, terminating\n",
                    (int)(i));
            }
            info->problemstatus = -3;
            ae_frame_leave(_state);
            return;
        }
    }
    for(i=0; i<=k-1; i++)
    {
        if( (ae_isfinite(al->ptr.p_double[i], _state)&&ae_isfinite(au->ptr.p_double[i], _state))&&ae_fp_greater(al->ptr.p_double[i],au->ptr.p_double[i]) )
        {
            if( dotrace )
            {
                ae_trace("> linear constraint %0d is found to have infeasible bounds, terminating\n",
                    (int)(i));
            }
            info->problemstatus = -3;
            ae_frame_leave(_state);
            return;
        }
    }
    for(i=0; i<=xccgetcount(xcc, _state)-1; i++)
    {
        ae_obj_array_get(&xcc->constraints, i, &_cc, _state);
        ae_assert(cc->conetype>=0, "PresolveNoneScaleUser: one of the conic constraints has non-canonic form", _state);
    }
    
    /*
     * Reallocate storage
     */
    rvectorgrowto(&info->rawc, n, _state);
    rvectorgrowto(&info->rawbndl, n, _state);
    rvectorgrowto(&info->rawbndu, n, _state);
    
    /*
     * Save original problem formulation
     */
    lpqppresolve_presolverstackinit(n, k, xqcgetcount(xqc, _state), xccgetcount(xcc, _state), &info->trfstack, _state);
    info->eps = ae_machineepsilon;
    info->problemstatus = 0;
    info->newn = n;
    info->oldn = n;
    info->newm = k;
    info->oldm = k;
    info->oldmqc = xqcgetcount(xqc, _state);
    info->newmqc = info->oldmqc;
    info->oldmcc = xccgetcount(xcc, _state);
    info->newmcc = info->oldmcc;
    bsetallocv(n, ae_false, &info->lagrangefromresidual, _state);
    iallocv(n, &info->packxperm, _state);
    iallocv(n, &info->unpackxperm, _state);
    for(i=0; i<=n-1; i++)
    {
        ae_assert(s->ptr.p_double[i]>(double)0, "PresolveNoneScaleUser: S<=0", _state);
        ae_assert(ae_isfinite(bndl->ptr.p_double[i], _state)||ae_isneginf(bndl->ptr.p_double[i], _state), "PresolveNoneScaleUser: BndL contains NAN or +INF", _state);
        ae_assert(ae_isfinite(bndu->ptr.p_double[i], _state)||ae_isposinf(bndu->ptr.p_double[i], _state), "PresolveNoneScaleUser: BndU contains NAN or -INF", _state);
        info->rawc.ptr.p_double[i] = c->ptr.p_double[i];
        info->rawbndl.ptr.p_double[i] = bndl->ptr.p_double[i];
        info->rawbndu.ptr.p_double[i] = bndu->ptr.p_double[i];
        info->packxperm.ptr.p_int[i] = i;
        info->unpackxperm.ptr.p_int[i] = i;
    }
    info->hash = hash;
    if( hash )
    {
        lpqppresolve_copyexpandh(sparseh, isupper, &info->rawh, _state);
        sparsecopybuf(&info->rawh, &info->sparseh, _state);
    }
    iallocv(k, &info->packyperm, _state);
    iallocv(k, &info->unpackyperm, _state);
    for(i=0; i<=k-1; i++)
    {
        info->packyperm.ptr.p_int[i] = i;
        info->unpackyperm.ptr.p_int[i] = i;
    }
    iallocv(info->newmqc, &info->packqcperm, _state);
    iallocv(info->newmqc, &info->unpackqcperm, _state);
    for(i=0; i<=info->newmqc-1; i++)
    {
        info->packqcperm.ptr.p_int[i] = i;
        info->unpackqcperm.ptr.p_int[i] = i;
    }
    iallocv(n+k, &info->packstatperm, _state);
    iallocv(n+k, &info->unpackstatperm, _state);
    for(i=0; i<=n+k-1; i++)
    {
        info->packstatperm.ptr.p_int[i] = i;
        info->unpackstatperm.ptr.p_int[i] = i;
    }
    sparsecopytocrsbuf(sparsea, &info->rawa, _state);
    xqccopy(xqc, &info->rawxqc, _state);
    xcccopy(xcc, &info->rawxcc, _state);
    
    /*
     * Scale cost and box constraints
     */
    rcopyallocv(n, c, &info->c, _state);
    rcopyallocv(n, bndl, &info->bndl, _state);
    rcopyallocv(n, bndu, &info->bndu, _state);
    if( k>0 )
    {
        rcopyallocv(k, al, &info->al, _state);
        rcopyallocv(k, au, &info->au, _state);
        sparsecopybuf(sparsea, &info->sparsea, _state);
    }
    xqccopy(xqc, &info->xqc, _state);
    xcccopy(xcc, &info->xcc, _state);
    lpqppresolve_scaleshiftobjectiveandconstraints(s, xorigin, n, &info->c, &info->bndl, &info->bndu, &info->sparseh, hash, &info->sparsea, &info->al, &info->au, k, &info->xqc, &info->xcc, &info->trfstack, _state);
    ae_frame_leave(_state);
}


/*************************************************************************
Extensive presolving for an LP problem, all techniques are used

INPUT PARAMETERS:
    S           -   array[N], user-supplied scale vector, S[I]>0
    C           -   array[N], costs
    BndL        -   array[N], lower bounds (may contain -INF)
    BndU        -   array[N], upper bounds (may contain +INF)
    N           -   variable count, N>0
    SparseA     -   matrix[K,N], sparse constraints
    AL          -   array[K], lower constraint bounds (may contain -INF)
    AU          -   array[K], upper constraint bounds (may contain +INF)
    K           -   constraint count, K>=0
    XQC         -   quadratic constraints; can be empty, but must be correctly
                    initialized with xqcInit()
    XCC         -   conic constraints; can be empty, but must be correctly
                    initialized with xccInit()
    Info        -   presolve info structure; temporaries allocated during
                    previous calls may be reused by this function.
                    
OUTPUT PARAMETERS:
    Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                    and   information   necessary   to   perform  backward
                    transformation.
                    Following fields can be acessed:
                    * Info.NewN>0  for transformed problem size
                    * Info.NewM>=0 for transformed constraint count
                    * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                    * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
    
NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void presolvelp(/* Real    */ const ae_vector* raws,
     /* Real    */ const ae_vector* rawc,
     /* Real    */ const ae_vector* rawbndl,
     /* Real    */ const ae_vector* rawbndu,
     ae_int_t n,
     const sparsematrix* rawsparsea,
     /* Real    */ const ae_vector* rawal,
     /* Real    */ const ae_vector* rawau,
     ae_int_t m,
     xquadraticconstraints* xqc,
     xconicconstraints* xcc,
     ae_bool dotrace,
     presolveinfo* presolved,
     ae_state *_state)
{
    ae_frame _frame_block;
    sparsematrix dummyh;
    ae_vector dummyorigin;

    ae_frame_make(_state, &_frame_block);
    memset(&dummyh, 0, sizeof(dummyh));
    memset(&dummyorigin, 0, sizeof(dummyorigin));
    _sparsematrix_init(&dummyh, _state, ae_true);
    ae_vector_init(&dummyorigin, 0, DT_REAL, _state, ae_true);

    rsetallocv(n, 0.0, &dummyorigin, _state);
    presolveqp(raws, &dummyorigin, rawc, rawbndl, rawbndu, &dummyh, ae_false, ae_false, n, rawsparsea, rawal, rawau, m, xqc, xcc, dotrace, presolved, _state);
    ae_frame_leave(_state);
}


/*************************************************************************
Extensive presolving for an QP problem, all techniques are used

INPUT PARAMETERS:
    S           -   array[N], user-supplied scale vector, S[I]>0
    C           -   array[N], costs
    BndL        -   array[N], lower bounds (may contain -INF)
    BndU        -   array[N], upper bounds (may contain +INF)
    H           -   if HasH=True, lower/upper triangular quadratic term
    HasH        -   if false, H is ignored
    N           -   variable count, N>0
    SparseA     -   matrix[K,N], sparse constraints
    AL          -   array[K], lower constraint bounds (may contain -INF)
    AU          -   array[K], upper constraint bounds (may contain +INF)
    K           -   constraint count, K>=0
    XQC         -   quadratic constraints; can be empty, but must be correctly
                    initialized with xqcInit(). Not modified, however it
                    is passed as shared because we access it with
                    objArray...() family of functions.
    XCC         -   conic constraints; can be empty, but must be correctly
                    initialized with xccInit(). Not modified, however it
                    is passed as shared because we access it with
                    objArray...() family of functions.
    Info        -   presolve info structure; temporaries allocated during
                    previous calls may be reused by this function.
                    
OUTPUT PARAMETERS:
    Info        -   contains transformed C, BndL, bndU,  SparseA,  AL,  AU
                    and   information   necessary   to   perform  backward
                    transformation.
                    Following fields can be acessed:
                    * Info.NewN>0  for transformed problem size
                    * Info.NewM>=0 for transformed constraint count
                    * always:          Info.C, Info.BndL, Info.BndU - array[NewN]
                    * for Info.NewM>0: Info.SparseA, Info.AL, Info.AU
    
NOTE: this routine does not reallocate arrays if NNew<=NOld and/or KNew<=KOld.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
void presolveqp(/* Real    */ const ae_vector* raws,
     /* Real    */ const ae_vector* xorigin,
     /* Real    */ const ae_vector* rawc,
     /* Real    */ const ae_vector* rawbndl,
     /* Real    */ const ae_vector* rawbndu,
     const sparsematrix* rawsparseh,
     ae_bool isupper,
     ae_bool hash,
     ae_int_t n,
     const sparsematrix* rawsparsea,
     /* Real    */ const ae_vector* rawal,
     /* Real    */ const ae_vector* rawau,
     ae_int_t m,
     xquadraticconstraints* rawxqc,
     xconicconstraints* rawxcc,
     ae_bool dotrace,
     presolveinfo* presolved,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_bool somethingchanged;
    sparsematrix normsparsea;
    sparsematrix normsparseat;
    xquadraticconstraints normxqc;
    xconicconstraints normxcc;
    dynamiccrs sparseh;
    dynamiccrs a;
    dynamiccrs at;
    dynamiccrsqconstraints qc;
    ae_vector c;
    ae_vector bndl;
    ae_vector bndu;
    ae_vector al;
    ae_vector au;
    ae_int_t i;
    ae_int_t k;
    ae_int_t j;
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t mqc;
    ae_int_t mcc;
    ae_int_t nv;
    ae_int_t offs;
    ae_int_t dbgemptycol;
    ae_int_t dbgemptyrow;
    ae_int_t dbgemptyqc;
    ae_int_t dbgnonbindingrows;
    ae_int_t dbgnonbindingqc;
    ae_int_t dbgfixed;
    ae_int_t dbgsingletonrow;
    ae_int_t dbgdoubletonrow;
    ae_int_t dbgslackvars;
    ae_int_t dbgimplicitslacks;
    ae_int_t dbgfreecolumnsingletons;
    double eps;
    ae_int_t presolverounds;
    sparsematrix sparsetmp;
    dynamiccrsqconstraint *qci;
    ae_smart_ptr _qci;
    xconicconstraint *cci;
    ae_smart_ptr _cci;
    xquadraticconstraint *xqci;
    ae_smart_ptr _xqci;
    presolvervcstats vcstats;
    ae_int_t kpow;
    ae_bool donecc;

    ae_frame_make(_state, &_frame_block);
    memset(&normsparsea, 0, sizeof(normsparsea));
    memset(&normsparseat, 0, sizeof(normsparseat));
    memset(&normxqc, 0, sizeof(normxqc));
    memset(&normxcc, 0, sizeof(normxcc));
    memset(&sparseh, 0, sizeof(sparseh));
    memset(&a, 0, sizeof(a));
    memset(&at, 0, sizeof(at));
    memset(&qc, 0, sizeof(qc));
    memset(&c, 0, sizeof(c));
    memset(&bndl, 0, sizeof(bndl));
    memset(&bndu, 0, sizeof(bndu));
    memset(&al, 0, sizeof(al));
    memset(&au, 0, sizeof(au));
    memset(&sparsetmp, 0, sizeof(sparsetmp));
    memset(&_qci, 0, sizeof(_qci));
    memset(&_cci, 0, sizeof(_cci));
    memset(&_xqci, 0, sizeof(_xqci));
    memset(&vcstats, 0, sizeof(vcstats));
    _sparsematrix_init(&normsparsea, _state, ae_true);
    _sparsematrix_init(&normsparseat, _state, ae_true);
    _xquadraticconstraints_init(&normxqc, _state, ae_true);
    _xconicconstraints_init(&normxcc, _state, ae_true);
    _dynamiccrs_init(&sparseh, _state, ae_true);
    _dynamiccrs_init(&a, _state, ae_true);
    _dynamiccrs_init(&at, _state, ae_true);
    _dynamiccrsqconstraints_init(&qc, _state, ae_true);
    ae_vector_init(&c, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndl, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&bndu, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&al, 0, DT_REAL, _state, ae_true);
    ae_vector_init(&au, 0, DT_REAL, _state, ae_true);
    _sparsematrix_init(&sparsetmp, _state, ae_true);
    ae_smart_ptr_init(&_qci, (void**)&qci, ae_false, _state, ae_true);
    ae_smart_ptr_init(&_cci, (void**)&cci, ae_false, _state, ae_true);
    ae_smart_ptr_init(&_xqci, (void**)&xqci, ae_false, _state, ae_true);
    _presolvervcstats_init(&vcstats, _state, ae_true);

    ae_assert(m==0||sparseiscrs(rawsparsea, _state), "PRESOLVER: A is non-CRS sparse matrix", _state);
    ae_assert(!hash||sparseiscrs(rawsparseh, _state), "PRESOLVER: quadratic term must be stored in the CRS format", _state);
    mqc = xqcgetcount(rawxqc, _state);
    mcc = xccgetcount(rawxcc, _state);
    
    /*
     * Trace
     */
    dotrace = (dotrace||(ae_is_trace_enabled("PRESOLVER.LP")&&!hash))||ae_is_trace_enabled("PRESOLVER.QP");
    if( dotrace )
    {
        ae_trace("\n\n");
        ae_trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
        if( hash )
        {
            ae_trace("// QP PRESOLVER STARTED                                                                           //\n");
        }
        else
        {
            ae_trace("// LP PRESOLVER STARTED                                                                           //\n");
        }
        ae_trace("////////////////////////////////////////////////////////////////////////////////////////////////////\n");
        ae_trace("----- printing input problem metrics ---------------------------------------------------------------\n");
        ae_trace("N            = %10d (variables)\n",
            (int)(n));
        ae_trace("M            = %10d (linear constraints)\n",
            (int)(m));
        if( m!=0 )
        {
            ae_trace("nz(A)        = %10d (nonzeros in linear constraints)\n",
                (int)(rawsparsea->ridx.ptr.p_int[rawsparsea->m]));
        }
        ae_trace("MQC          = %10d (quadratic constraints)\n",
            (int)(mqc));
        ae_trace("MCC          = %10d (conic constraints)\n",
            (int)(mcc));
    }
    
    /*
     * Initial check for constraint feasibility
     */
    for(i=0; i<=n-1; i++)
    {
        if( (ae_isfinite(rawbndl->ptr.p_double[i], _state)&&ae_isfinite(rawbndu->ptr.p_double[i], _state))&&ae_fp_greater(rawbndl->ptr.p_double[i],rawbndu->ptr.p_double[i]) )
        {
            if( dotrace )
            {
                ae_trace("> variable %0d is found to have infeasible box constraints, terminating\n",
                    (int)(i));
            }
            presolved->problemstatus = -3;
            ae_frame_leave(_state);
            return;
        }
    }
    for(i=0; i<=m-1; i++)
    {
        if( (ae_isfinite(rawal->ptr.p_double[i], _state)&&ae_isfinite(rawau->ptr.p_double[i], _state))&&ae_fp_greater(rawal->ptr.p_double[i],rawau->ptr.p_double[i]) )
        {
            if( dotrace )
            {
                ae_trace("> linear constraint %0d is found to have infeasible bounds, terminating\n",
                    (int)(i));
            }
            presolved->problemstatus = -3;
            ae_frame_leave(_state);
            return;
        }
    }
    for(i=0; i<=mqc-1; i++)
    {
        ae_obj_array_get(&rawxqc->constraints, i, &_xqci, _state);
        if( (ae_isfinite(xqci->cl, _state)&&ae_isfinite(xqci->cu, _state))&&ae_fp_greater(xqci->cl,xqci->cu) )
        {
            if( dotrace )
            {
                ae_trace("> quadratic constraint %0d is found to have infeasible bounds, terminating\n",
                    (int)(i));
            }
            presolved->problemstatus = -3;
            ae_frame_leave(_state);
            return;
        }
    }
    
    /*
     * Starting output
     */
    rcopyallocv(n, rawc, &presolved->rawc, _state);
    rcopyallocv(n, rawbndl, &presolved->rawbndl, _state);
    rcopyallocv(n, rawbndu, &presolved->rawbndu, _state);
    if( m>0 )
    {
        sparsecopytocrsbuf(rawsparsea, &presolved->rawa, _state);
    }
    xqccopy(rawxqc, &presolved->rawxqc, _state);
    xcccopy(rawxcc, &presolved->rawxcc, _state);
    presolved->hash = hash;
    if( hash )
    {
        lpqppresolve_copyexpandh(rawsparseh, isupper, &presolved->rawh, _state);
    }
    
    /*
     * Trace counters
     */
    dbgemptycol = 0;
    dbgemptyrow = 0;
    dbgemptyqc = 0;
    dbgnonbindingrows = 0;
    dbgnonbindingqc = 0;
    dbgfixed = 0;
    dbgsingletonrow = 0;
    dbgdoubletonrow = 0;
    dbgslackvars = 0;
    dbgimplicitslacks = 0;
    dbgfreecolumnsingletons = 0;
    
    /*
     * Initial state of the presolver
     */
    eps = (double)(1000+n+m)*ae_machineepsilon+ae_pow(ae_machineepsilon, 0.75, _state);
    presolved->eps = eps;
    lpqppresolve_presolverstackinit(n, m, xqcgetcount(rawxqc, _state), xccgetcount(rawxcc, _state), &presolved->trfstack, _state);
    presolved->problemstatus = 0;
    rcopyallocv(n, rawc, &c, _state);
    rcopyallocv(n, rawbndl, &bndl, _state);
    rcopyallocv(n, rawbndu, &bndu, _state);
    if( m>0 )
    {
        sparsecopybuf(rawsparsea, &normsparsea, _state);
        rcopyallocv(m, rawal, &al, _state);
        rcopyallocv(m, rawau, &au, _state);
    }
    xqccopy(rawxqc, &normxqc, _state);
    xcccopy(rawxcc, &normxcc, _state);
    if( hash )
    {
        sparsecopybuf(&presolved->rawh, &sparsetmp, _state);
    }
    lpqppresolve_scaleshiftobjectiveandconstraints(raws, xorigin, n, &c, &bndl, &bndu, &sparsetmp, hash, &normsparsea, &al, &au, m, &normxqc, &normxcc, &presolved->trfstack, _state);
    if( hash )
    {
        dyncrsinitfromsparsecrs(&sparsetmp, &sparseh, _state);
        dyncrsdropoffdiagonalzeros(&sparseh, _state);
    }
    if( m>0 )
    {
        sparsecopytransposecrsbuf(&normsparsea, &normsparseat, _state);
        dyncrsinitfromsparsecrs(&normsparsea, &a, _state);
        dyncrsinitfromsparsecrs(&normsparseat, &at, _state);
        dyncrsdropzeros(&a, _state);
        dyncrsdropzeros(&at, _state);
    }
    else
    {
        dyncrsinitempty(&a, 0, n, _state);
        dyncrsinitempty(&at, n, 0, _state);
    }
    bsetallocv(n, ae_false, &presolved->lagrangefromresidual, _state);
    lpqppresolve_presolvebuffersinit(&presolved->buf, n, m, _state);
    
    /*
     * Initial state of QC and CC-related variables
     */
    bsetallocv(n, ae_false, &vcstats.isdroppedcol, _state);
    bsetallocv(m, ae_false, &vcstats.isdroppedlc, _state);
    isetallocv(n, 0, &vcstats.nlcpervar, _state);
    isetallocv(n, 0, &vcstats.cntdownwardaxial, _state);
    isetallocv(n, 0, &vcstats.cntupwardaxial, _state);
    isetallocv(n, 0, &vcstats.cntaxial, _state);
    isetallocv(n, 0, &vcstats.cntradial, _state);
    lpqppresolve_dynqcinitfromxqc(&normxqc, &qc, _state);
    bsetallocv(mqc, ae_false, &vcstats.isdroppedqc, _state);
    knisinitunsorted(n, mqc, 0, &vcstats.varbyqc, _state);
    for(i=0; i<=mqc-1; i++)
    {
        ae_obj_array_get(&qc.constraints, i, &_qci, _state);
        for(j=0; j<=qci->nvars-1; j++)
        {
            k = qci->varidx.ptr.p_int[j];
            vcstats.nlcpervar.ptr.p_int[k] = vcstats.nlcpervar.ptr.p_int[k]+1;
            knisaddnewelement(&vcstats.varbyqc, k, i, _state);
        }
    }
    bsetallocv(mcc, ae_false, &vcstats.isdroppedcc, _state);
    knisinitunsorted(n, mcc, 0, &vcstats.varbycc, _state);
    for(i=0; i<=mcc-1; i++)
    {
        ae_obj_array_get(&normxcc.constraints, i, &_cci, _state);
        nv = cci->nvars;
        for(j=0; j<=nv-1; j++)
        {
            k = cci->varidx.ptr.p_int[j];
            vcstats.nlcpervar.ptr.p_int[k] = vcstats.nlcpervar.ptr.p_int[k]+1;
            knisaddnewelement(&vcstats.varbycc, k, i, _state);
        }
        donecc = ae_false;
        if( cci->conetype==xccprimitiveconetype(_state) )
        {
            for(j=0; j<=nv-2; j++)
            {
                vcstats.cntradial.ptr.p_int[cci->varidx.ptr.p_int[j]] = vcstats.cntradial.ptr.p_int[cci->varidx.ptr.p_int[j]]+1;
            }
            k = cci->varidx.ptr.p_int[nv-1];
            vcstats.cntaxial.ptr.p_int[k] = vcstats.cntaxial.ptr.p_int[k]+1;
            if( ae_fp_greater(cci->diaga.ptr.p_double[nv-1],(double)(0)) )
            {
                vcstats.cntupwardaxial.ptr.p_int[k] = vcstats.cntupwardaxial.ptr.p_int[k]+1;
            }
            if( ae_fp_less(cci->diaga.ptr.p_double[nv-1],(double)(0)) )
            {
                vcstats.cntdownwardaxial.ptr.p_int[k] = vcstats.cntdownwardaxial.ptr.p_int[k]+1;
            }
            donecc = ae_true;
        }
        if( cci->conetype==xccprimitivepowerconetype(_state) )
        {
            kpow = cci->kpow;
            for(j=0; j<=nv-kpow-1; j++)
            {
                vcstats.cntradial.ptr.p_int[cci->varidx.ptr.p_int[j]] = vcstats.cntradial.ptr.p_int[cci->varidx.ptr.p_int[j]]+1;
            }
            for(j=nv-kpow; j<=nv-1; j++)
            {
                k = cci->varidx.ptr.p_int[j];
                vcstats.cntaxial.ptr.p_int[k] = vcstats.cntaxial.ptr.p_int[k]+1;
                if( ae_fp_greater(cci->diaga.ptr.p_double[j],(double)(0)) )
                {
                    vcstats.cntupwardaxial.ptr.p_int[k] = vcstats.cntupwardaxial.ptr.p_int[k]+1;
                }
                if( ae_fp_less(cci->diaga.ptr.p_double[j],(double)(0)) )
                {
                    vcstats.cntdownwardaxial.ptr.p_int[k] = vcstats.cntdownwardaxial.ptr.p_int[k]+1;
                }
            }
            donecc = ae_true;
        }
        ae_assert(donecc, "PRESOLVER: integrity check 485227 failed", _state);
    }
    
    /*
     * While something changes, keep iterating
     */
    presolverounds = 0;
    somethingchanged = ae_true;
    while(somethingchanged)
    {
        somethingchanged = ae_false;
        if( !lpqppresolve_dropemptycol(&c, &bndl, &bndu, &vcstats, &presolved->lagrangefromresidual, &sparseh, hash, n, &a, &at, &al, &au, m, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgemptycol, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        if( !lpqppresolve_dropclearlynonbindingrows(n, &vcstats, &a, &at, &al, &au, m, &qc, &normxcc, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgemptyrow, &dbgemptyqc, &dbgnonbindingrows, &dbgnonbindingqc, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        if( !lpqppresolve_singletonrowtobc(&bndl, &bndu, &vcstats, n, &a, &at, &al, &au, m, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgsingletonrow, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        if( !lpqppresolve_doubletonrow(&c, &bndl, &bndu, &vcstats, &sparseh, hash, n, &a, &at, &al, &au, m, &qc, &normxcc, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgdoubletonrow, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        if( !lpqppresolve_fixvariables(&c, &bndl, &bndu, &vcstats, &sparseh, hash, n, &a, &at, &al, &au, m, &qc, &normxcc, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgfixed, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        if( !lpqppresolve_singletoncols(&c, &bndl, &bndu, &vcstats, &sparseh, hash, n, &a, &at, &al, &au, m, eps, dotrace, &presolved->buf, &presolved->trfstack, &presolved->problemstatus, &somethingchanged, &dbgslackvars, &dbgimplicitslacks, &dbgfreecolumnsingletons, _state) )
        {
            ae_frame_leave(_state);
            return;
        }
        presolverounds = presolverounds+1;
    }
    
    /*
     * Integrity checks
     * * A and AT have the same number of elements (we do not check actual elements, only their total count)
     * * VCStats.NLCPerVar is zero after we subtract all non-dropped constraints
     */
    if( m>0 )
    {
        j0 = 0;
        for(j=0; j<=m-1; j++)
        {
            j0 = j0+(a.rowend.ptr.p_int[j]-a.rowbegin.ptr.p_int[j]);
        }
        j1 = 0;
        for(j=0; j<=n-1; j++)
        {
            j1 = j1+(at.rowend.ptr.p_int[j]-at.rowbegin.ptr.p_int[j]);
        }
        ae_assert(j0==j1, "PRESOLVER: integrity check 4347 failed", _state);
    }
    for(i=0; i<=n-1; i++)
    {
        ae_assert(vcstats.nlcpervar.ptr.p_int[i]==kniscountkth(&vcstats.varbyqc, i, _state)+kniscountkth(&vcstats.varbycc, i, _state), "PRESOLVER: integrity check 566152 failed", _state);
    }
    for(i=0; i<=mqc-1; i++)
    {
        if( vcstats.isdroppedqc.ptr.p_bool[i] )
        {
            continue;
        }
        ae_obj_array_get(&qc.constraints, i, &_qci, _state);
        for(j=0; j<=qci->nvars-1; j++)
        {
            if( vcstats.isdroppedcol.ptr.p_bool[qci->varidx.ptr.p_int[j]] )
            {
                ae_assert(ae_false, "PRESOLVER: integrity check 2602 failed", _state);
            }
            vcstats.nlcpervar.ptr.p_int[qci->varidx.ptr.p_int[j]] = vcstats.nlcpervar.ptr.p_int[qci->varidx.ptr.p_int[j]]-1;
        }
    }
    for(i=0; i<=mcc-1; i++)
    {
        if( vcstats.isdroppedcc.ptr.p_bool[i] )
        {
            continue;
        }
        ae_obj_array_get(&normxcc.constraints, i, &_cci, _state);
        for(j=0; j<=cci->nvars-1; j++)
        {
            if( vcstats.isdroppedcol.ptr.p_bool[cci->varidx.ptr.p_int[j]] )
            {
                ae_assert(ae_false, "PRESOLVER: integrity check 529049 failed", _state);
            }
            vcstats.nlcpervar.ptr.p_int[cci->varidx.ptr.p_int[j]] = vcstats.nlcpervar.ptr.p_int[cci->varidx.ptr.p_int[j]]-1;
        }
    }
    for(i=0; i<=n-1; i++)
    {
        if( vcstats.nlcpervar.ptr.p_int[i]!=0 )
        {
            ae_assert(ae_false, "PRESOLVER: integrity check 3303 failed", _state);
        }
    }
    
    /*
     * Output data that are permuted by XPerm[]
     */
    presolved->oldn = n;
    presolved->newn = 0;
    isetallocv(n, -1, &presolved->packxperm, _state);
    isetallocv(n, -1, &presolved->unpackxperm, _state);
    for(i=0; i<=n-1; i++)
    {
        if( !vcstats.isdroppedcol.ptr.p_bool[i] )
        {
            presolved->unpackxperm.ptr.p_int[presolved->newn] = i;
            presolved->packxperm.ptr.p_int[i] = presolved->newn;
            presolved->newn = presolved->newn+1;
        }
    }
    rallocv(presolved->newn, &presolved->bndl, _state);
    rallocv(presolved->newn, &presolved->bndu, _state);
    rallocv(presolved->newn, &presolved->c, _state);
    for(i=0; i<=presolved->newn-1; i++)
    {
        presolved->c.ptr.p_double[i] = c.ptr.p_double[presolved->unpackxperm.ptr.p_int[i]];
        presolved->bndl.ptr.p_double[i] = bndl.ptr.p_double[presolved->unpackxperm.ptr.p_int[i]];
        presolved->bndu.ptr.p_double[i] = bndu.ptr.p_double[presolved->unpackxperm.ptr.p_int[i]];
    }
    if( hash )
    {
        presolved->sparseh.n = presolved->newn;
        presolved->sparseh.m = presolved->newn;
        iallocv(presolved->newn+1, &presolved->sparseh.ridx, _state);
        presolved->sparseh.ridx.ptr.p_int[0] = 0;
        for(i=0; i<=presolved->newn-1; i++)
        {
            offs = presolved->sparseh.ridx.ptr.p_int[i];
            igrowv(offs+n, &presolved->sparseh.idx, _state);
            rgrowv(offs+n, &presolved->sparseh.vals, _state);
            k = presolved->unpackxperm.ptr.p_int[i];
            j0 = sparseh.rowbegin.ptr.p_int[k];
            j1 = sparseh.rowend.ptr.p_int[k]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                j = presolved->packxperm.ptr.p_int[sparseh.idx.ptr.p_int[jj]];
                if( j<0||j>i )
                {
                    continue;
                }
                presolved->sparseh.idx.ptr.p_int[offs] = j;
                presolved->sparseh.vals.ptr.p_double[offs] = sparseh.vals.ptr.p_double[jj];
                offs = offs+1;
            }
            presolved->sparseh.ridx.ptr.p_int[i+1] = offs;
        }
        sparsecreatecrsinplace(&presolved->sparseh, _state);
    }
    
    /*
     * Output data that are permuted by YPerm[]
     */
    presolved->oldm = m;
    presolved->newm = 0;
    isetallocv(m, -1, &presolved->packyperm, _state);
    isetallocv(m, -1, &presolved->unpackyperm, _state);
    for(i=0; i<=m-1; i++)
    {
        if( !vcstats.isdroppedlc.ptr.p_bool[i] )
        {
            presolved->unpackyperm.ptr.p_int[presolved->newm] = i;
            presolved->packyperm.ptr.p_int[i] = presolved->newm;
            presolved->newm = presolved->newm+1;
        }
    }
    rallocv(presolved->newm, &presolved->al, _state);
    rallocv(presolved->newm, &presolved->au, _state);
    for(i=0; i<=presolved->newm-1; i++)
    {
        presolved->al.ptr.p_double[i] = al.ptr.p_double[presolved->unpackyperm.ptr.p_int[i]];
        presolved->au.ptr.p_double[i] = au.ptr.p_double[presolved->unpackyperm.ptr.p_int[i]];
    }
    
    /*
     * Output A which is permuted by both XPerm[] and YPerm[]
     */
    presolved->sparsea.m = 0;
    presolved->sparsea.n = presolved->newn;
    iallocv(presolved->newm+1, &presolved->sparsea.ridx, _state);
    presolved->sparsea.ridx.ptr.p_int[0] = 0;
    for(i=0; i<=m-1; i++)
    {
        if( !vcstats.isdroppedlc.ptr.p_bool[i] )
        {
            offs = presolved->sparsea.ridx.ptr.p_int[presolved->sparsea.m];
            igrowv(offs+n, &presolved->sparsea.idx, _state);
            rgrowv(offs+n, &presolved->sparsea.vals, _state);
            j0 = a.rowbegin.ptr.p_int[i];
            j1 = a.rowend.ptr.p_int[i]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                j = presolved->packxperm.ptr.p_int[a.idx.ptr.p_int[jj]];
                ae_assert(j>=0, "PRESOLVE: integrity check 54fc failed", _state);
                presolved->sparsea.idx.ptr.p_int[offs] = j;
                presolved->sparsea.vals.ptr.p_double[offs] = a.vals.ptr.p_double[jj];
                offs = offs+1;
            }
            presolved->sparsea.m = presolved->sparsea.m+1;
            presolved->sparsea.ridx.ptr.p_int[presolved->sparsea.m] = offs;
        }
    }
    ae_assert(presolved->sparsea.m==presolved->newm, "PRESOLVE: integrity check ee3a failed", _state);
    sparsecreatecrsinplace(&presolved->sparsea, _state);
    
    /*
     * Output data permuted by QCPerm[] and XPerm[]
     */
    presolved->xqc.n = n;
    ae_obj_array_clear(&presolved->xqc.constraints);
    presolved->oldmqc = mqc;
    presolved->newmqc = 0;
    isetallocv(mqc, -1, &presolved->packqcperm, _state);
    isetallocv(mqc, -1, &presolved->unpackqcperm, _state);
    for(i=0; i<=mqc-1; i++)
    {
        if( !vcstats.isdroppedqc.ptr.p_bool[i] )
        {
            presolved->unpackqcperm.ptr.p_int[presolved->newmqc] = i;
            presolved->packqcperm.ptr.p_int[i] = presolved->newmqc;
            presolved->newmqc = presolved->newmqc+1;
            ae_obj_array_get(&qc.constraints, i, &_qci, _state);
            xqci = (xquadraticconstraint*)ae_malloc(sizeof(xquadraticconstraint), _state); /* note: using xqci as a temporary prior to assigning its value to _xqci */
            memset(xqci, 0, sizeof(xquadraticconstraint));
            _xquadraticconstraint_init(xqci, _state, ae_false);
            ae_smart_ptr_assign(&_xqci, xqci, ae_true, ae_true, (ae_int_t)sizeof(xquadraticconstraint), _xquadraticconstraint_init_copy, _xquadraticconstraint_destroy);
            lpqppresolve_dynqcpermtoxqc(qci, &presolved->packxperm, &presolved->unpackxperm, xqci, _state);
            ae_obj_array_append_transfer(&presolved->xqc.constraints, &_xqci, _state);
        }
    }
    
    /*
     * Output data permuted by CCPerm and XPerm
     */
    presolved->oldmcc = mcc;
    presolved->newmcc = 0;
    isetallocv(mcc, -1, &presolved->packccperm, _state);
    isetallocv(mcc, -1, &presolved->unpackccperm, _state);
    for(i=0; i<=mcc-1; i++)
    {
        if( !vcstats.isdroppedcc.ptr.p_bool[i] )
        {
            presolved->unpackccperm.ptr.p_int[presolved->newmcc] = i;
            presolved->packccperm.ptr.p_int[i] = presolved->newmcc;
            presolved->newmcc = presolved->newmcc+1;
        }
    }
    xcccopywithskipandpack(&normxcc, &vcstats.isdroppedcc, &presolved->packxperm, &presolved->xcc, _state);
    ae_assert(presolved->newmcc==xccgetcount(&presolved->xcc, _state), "PRESOLVER: integrity check 682108 failed", _state);
    
    /*
     * Prepare permutation for constraint Stats[]
     */
    isetallocv(n+m, -1, &presolved->packstatperm, _state);
    isetallocv(n+m, -1, &presolved->unpackstatperm, _state);
    offs = 0;
    for(i=0; i<=n-1; i++)
    {
        if( !vcstats.isdroppedcol.ptr.p_bool[i] )
        {
            presolved->packstatperm.ptr.p_int[i] = offs;
            offs = offs+1;
        }
    }
    for(i=0; i<=m-1; i++)
    {
        if( !vcstats.isdroppedlc.ptr.p_bool[i] )
        {
            presolved->packstatperm.ptr.p_int[n+i] = offs;
            offs = offs+1;
        }
    }
    ae_assert(offs==presolved->newn+presolved->newm, "PRESOLVE: integrity check 3632 failed", _state);
    for(i=0; i<=n+m-1; i++)
    {
        if( presolved->packstatperm.ptr.p_int[i]>=0 )
        {
            presolved->unpackstatperm.ptr.p_int[presolved->packstatperm.ptr.p_int[i]] = i;
        }
    }
    
    /*
     * Trace output
     */
    if( dotrace )
    {
        ae_trace("done in %0d rounds\n\n",
            (int)(presolverounds));
        ae_trace("----- printing information about reductions --------------------------------------------------------\n");
        ae_trace("fixed vars           = %10d (fixed variables)\n",
            (int)(dbgfixed));
        ae_trace("empty cols           = %10d (empty constraint columns)\n",
            (int)(dbgemptycol));
        ae_trace("empty rows           = %10d (empty constraint rows)\n",
            (int)(dbgemptyrow));
        ae_trace("empty QC             = %10d (empty quadratic constraints)\n",
            (int)(dbgemptyqc));
        ae_trace("nonbinding rows      = %10d (irrelevant LC due to bounds)\n",
            (int)(dbgnonbindingrows));
        ae_trace("nonbinding QC        = %10d (irrelevant QC due to bounds)\n",
            (int)(dbgnonbindingqc));
        ae_trace("singleton rows       = %10d (singleton rows converted to box constraints)\n",
            (int)(dbgsingletonrow));
        ae_trace("doubleton rows       = %10d (doubleton equality constraints used to factor out variables)\n",
            (int)(dbgdoubletonrow));
        ae_trace("slack variables      = %10d (singleton cols with zero cost, recognized as explicit slacks)\n",
            (int)(dbgslackvars));
        ae_trace("implicit slacks      = %10d (singleton cols at equality rows, recognized as implicit slacks)\n",
            (int)(dbgimplicitslacks));
        ae_trace("free col singletons  = %10d (free singleton columns)\n",
            (int)(dbgfreecolumnsingletons));
        ae_trace("----- printing output problem metrics --------------------------------------------------------------\n");
        ae_trace("N            = %10d (variables)\n",
            (int)(presolved->newn));
        ae_trace("M            = %10d (constraints)\n",
            (int)(presolved->newm));
        ae_trace("MQC          = %10d (quadratic constraints)\n",
            (int)(presolved->newmqc));
        if( m!=0 )
        {
            ae_trace("nz(A)        = %10d (nonzeros in A)\n",
                (int)(presolved->sparsea.ridx.ptr.p_int[presolved->sparsea.m]));
        }
    }
    ae_frame_leave(_state);
}


/*************************************************************************
Forward transformation which transforms a set of original variables (e.g.
an initial point) to the converted problem format.

INPUT PARAMETERS:
    Info        -   presolve info structure
    X           -   array[NOld], original point
                    
OUTPUT PARAMETERS:
    X           -   array[NNew], transformed point
    
NOTE: this routine does not reallocate arrays if NOld<=NNew and/or KOld<=KNew.

  -- ALGLIB --
     Copyright 01.07.2020 by Bochkanov Sergey
*************************************************************************/
void presolvefwd(presolveinfo* s,
     /* Real    */ ae_vector* xx,
     ae_state *_state)
{
    ae_int_t tidx;
    ae_int_t tt;
    ae_int_t i;
    ae_int_t k;
    double v;


    rcopyallocv(s->oldn, xx, &s->x1, _state);
    for(tidx=0; tidx<=s->trfstack.ntrf-1; tidx++)
    {
        tt = s->trfstack.trftype.ptr.p_int[tidx];
        if( tt==lpqppresolve_pstobjectivescaling )
        {
            continue;
        }
        if( tt==lpqppresolve_pstcolscaling )
        {
            
            /*
             * Column scaling
             */
            lpqppresolve_presolverselectstreamsource(&s->trfstack, tidx, _state);
            lpqppresolve_presolverunstreamir(&s->trfstack, &k, &v, _state);
            lpqppresolve_presolverasserteos(&s->trfstack, _state);
            s->x1.ptr.p_double[k] = s->x1.ptr.p_double[k]*v;
            continue;
        }
        if( tt==lpqppresolve_pstcolshifting )
        {
            
            /*
             * Variable shifting
             */
            lpqppresolve_presolverselectstreamsource(&s->trfstack, tidx, _state);
            lpqppresolve_presolverunstreamir(&s->trfstack, &k, &v, _state);
            lpqppresolve_presolverasserteos(&s->trfstack, _state);
            s->x1.ptr.p_double[k] = s->x1.ptr.p_double[k]+v;
            continue;
        }
        if( tt==lpqppresolve_pstrowscaling )
        {
            continue;
        }
        if( tt==lpqppresolve_pstqcscaling )
        {
            continue;
        }
        if( tt==lpqppresolve_pstdropemptycol )
        {
            continue;
        }
        if( tt==lpqppresolve_pstdropemptyrow )
        {
            continue;
        }
        if( tt==lpqppresolve_pstdropemptyqc )
        {
            continue;
        }
        if( tt==lpqppresolve_pstsingletonrow )
        {
            continue;
        }
        if( tt==lpqppresolve_pstfixedvar )
        {
            continue;
        }
        if( tt==lpqppresolve_pstexplicitslack )
        {
            continue;
        }
        if( tt==lpqppresolve_pstimplicitslack )
        {
            continue;
        }
        if( tt==lpqppresolve_pstdoubletoneq )
        {
            continue;
        }
        ae_assert(ae_false, "PresolverFwd: unexpected transform type", _state);
    }
    rallocv(s->newn, xx, _state);
    for(i=0; i<=s->newn-1; i++)
    {
        xx->ptr.p_double[i] = s->x1.ptr.p_double[s->unpackxperm.ptr.p_int[i]];
    }
}


/*************************************************************************
Backward transformation which extracts original solution from that of  the
converted problem.

Below NNew/KNew correspond to transformed problem size (as returned by the
presolve routine) and NOld/KOld correspond to original  problem  size  (as
specified by caller). We expect that caller knows  these  sizes,  so  this
routine does not report them.

INPUT PARAMETERS:
    Info        -   presolve info structure
    X           -   array[NNew], transformed solution (primal variables)
    Stats       -   array[NNew+MNew], transformed constraint status (negative -
                    at lower bound, positive -  at  upper  bound,  zero  -
                    inactive).
    LagBC       -   array[NNew], transformed Lagrange multipliers
    LagLC       -   array[KNew], transformed Lagrange multipliers
    LagQC       -   array[MQCNew], transformed Lagrange multipliers
                    
OUTPUT PARAMETERS:
    X           -   array[NOld], original solution (primal variables)
    Stats       -   array[NOld+MOld], original constraint status
    LagBC       -   array[NOld], Lagrange multipliers
    LagLC       -   array[KOld], Lagrange multipliers
    LagQC       -   array[MQCOld], transformed Lagrange multipliers
    
NOTE: this routine does not reallocate arrays if NOld<=NNew and/or KOld<=KNew.

  -- ALGLIB --
     Copyright 01.07.2020 by Bochkanov Sergey
*************************************************************************/
void presolvebwd(presolveinfo* info,
     /* Real    */ ae_vector* x,
     /* Integer */ ae_vector* stats,
     ae_bool needstats,
     /* Real    */ ae_vector* lagbc,
     /* Real    */ ae_vector* laglc,
     /* Real    */ ae_vector* lagqc,
     ae_state *_state)
{
    ae_int_t i;


    
    /*
     * Read state of the transformed problem into storage allocated for the original problem
     */
    if( needstats )
    {
        isetallocv(info->oldn+info->oldm, 0, &info->s1, _state);
        for(i=0; i<=info->newn+info->newm-1; i++)
        {
            info->s1.ptr.p_int[info->unpackstatperm.ptr.p_int[i]] = stats->ptr.p_int[i];
        }
    }
    rsetallocv(info->oldn, 0.0, &info->x1, _state);
    for(i=0; i<=info->newn-1; i++)
    {
        info->x1.ptr.p_double[info->unpackxperm.ptr.p_int[i]] = x->ptr.p_double[i];
    }
    rsetallocv(info->oldn, 0.0, &info->bc1, _state);
    for(i=0; i<=info->newn-1; i++)
    {
        info->bc1.ptr.p_double[info->unpackxperm.ptr.p_int[i]] = lagbc->ptr.p_double[i];
    }
    rsetallocv(info->oldm, 0.0, &info->y1, _state);
    for(i=0; i<=info->newm-1; i++)
    {
        info->y1.ptr.p_double[info->unpackyperm.ptr.p_int[i]] = laglc->ptr.p_double[i];
    }
    rsetallocv(info->oldmqc, 0.0, &info->yqc, _state);
    for(i=0; i<=info->newmqc-1; i++)
    {
        info->yqc.ptr.p_double[info->unpackqcperm.ptr.p_int[i]] = lagqc->ptr.p_double[i];
    }
    
    /*
     * Apply reverse transformation
     */
    lpqppresolve_presolverrestoresolution(&info->trfstack, &info->x1, &info->bc1, &info->y1, &info->yqc, &info->s1, needstats, info->eps, _state);
    
    /*
     * Polish X according to box constraints and info from newly recovered Stats[]
     * Recompute coefficients corresponding to variables fixed during presolve using residual costs.
     */
    for(i=0; i<=info->oldn-1; i++)
    {
        if( ae_isfinite(info->rawbndl.ptr.p_double[i], _state) )
        {
            info->x1.ptr.p_double[i] = ae_maxreal(info->x1.ptr.p_double[i], info->rawbndl.ptr.p_double[i], _state);
        }
        if( ae_isfinite(info->rawbndu.ptr.p_double[i], _state) )
        {
            info->x1.ptr.p_double[i] = ae_minreal(info->x1.ptr.p_double[i], info->rawbndu.ptr.p_double[i], _state);
        }
        if( needstats )
        {
            if( info->s1.ptr.p_int[i]<0 )
            {
                info->x1.ptr.p_double[i] = info->rawbndl.ptr.p_double[i];
            }
            if( info->s1.ptr.p_int[i]>0 )
            {
                info->x1.ptr.p_double[i] = info->rawbndu.ptr.p_double[i];
            }
        }
    }
    rcopyallocv(info->oldn, &info->rawc, &info->d, _state);
    if( info->oldm>0 )
    {
        sparsegemv(&info->rawa, 1.0, 1, &info->y1, 0, 1.0, &info->d, 0, _state);
    }
    for(i=0; i<=info->oldn-1; i++)
    {
        if( info->lagrangefromresidual.ptr.p_bool[i] )
        {
            info->bc1.ptr.p_double[i] = -info->d.ptr.p_double[i];
        }
    }
    
    /*
     * Output
     */
    rcopyallocv(info->oldn, &info->x1, x, _state);
    rcopyallocv(info->oldmqc, &info->yqc, lagqc, _state);
    rcopyallocv(info->oldm, &info->y1, laglc, _state);
    if( needstats )
    {
        icopyallocv(info->oldn+info->oldm, &info->s1, stats, _state);
    }
    rcopyallocv(info->oldn, &info->bc1, lagbc, _state);
}


/*************************************************************************
Returns true if both bounds are finite and the difference is less than Eps.

Used to provide consistent way of checking for fixed vars across the unit.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static ae_bool lpqppresolve_isfixed(double bndl,
     double bndu,
     double eps,
     ae_state *_state)
{
    ae_bool result;


    result = (ae_isfinite(bndl, _state)&&ae_isfinite(bndu, _state))&&ae_fp_greater_eq(bndl,bndu-eps);
    return result;
}


/*************************************************************************
Initialize dynamic-CRS-based quadratic constraints from the standard ones

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqcinitfromxqc(xquadraticconstraints* src,
     dynamiccrsqconstraints* dst,
     ae_state *_state)
{
    ae_frame _frame_block;
    ae_int_t i;
    ae_int_t cnt;
    ae_int_t nv;
    xquadraticconstraint *qcsrc;
    ae_smart_ptr _qcsrc;
    dynamiccrsqconstraint *qcdst;
    ae_smart_ptr _qcdst;
    sparsematrix fullq;

    ae_frame_make(_state, &_frame_block);
    memset(&_qcsrc, 0, sizeof(_qcsrc));
    memset(&_qcdst, 0, sizeof(_qcdst));
    memset(&fullq, 0, sizeof(fullq));
    ae_smart_ptr_init(&_qcsrc, (void**)&qcsrc, ae_false, _state, ae_true);
    ae_smart_ptr_init(&_qcdst, (void**)&qcdst, ae_false, _state, ae_true);
    _sparsematrix_init(&fullq, _state, ae_true);

    cnt = xqcgetcount(src, _state);
    ae_obj_array_clear(&dst->constraints);
    for(i=0; i<=cnt-1; i++)
    {
        ae_obj_array_get(&src->constraints, i, &_qcsrc, _state);
        qcdst = (dynamiccrsqconstraint*)ae_malloc(sizeof(dynamiccrsqconstraint), _state); /* note: using qcdst as a temporary prior to assigning its value to _qcdst */
        memset(qcdst, 0, sizeof(dynamiccrsqconstraint));
        _dynamiccrsqconstraint_init(qcdst, _state, ae_false);
        ae_smart_ptr_assign(&_qcdst, qcdst, ae_true, ae_true, (ae_int_t)sizeof(dynamiccrsqconstraint), _dynamiccrsqconstraint_init_copy, _dynamiccrsqconstraint_destroy);
        nv = qcsrc->nvars;
        qcdst->nvars = nv;
        qcdst->cl = qcsrc->cl;
        qcdst->cu = qcsrc->cu;
        qcdst->applyorigin = qcsrc->applyorigin;
        if( nv>0 )
        {
            icopyallocv(nv, &qcsrc->varidx, &qcdst->varidx, _state);
            rcopyallocv(nv, &qcsrc->b, &qcdst->b, _state);
            lpqppresolve_copyexpandh(&qcsrc->lowerq, ae_false, &fullq, _state);
            dyncrsinitfromsparsecrs(&fullq, &qcdst->fullq, _state);
        }
        ae_obj_array_append_transfer(&dst->constraints, &_qcdst, _state);
    }
    ae_frame_leave(_state);
}


/*************************************************************************
Copy structure

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqccopy(const dynamiccrsqconstraint* src,
     dynamiccrsqconstraint* dst,
     ae_state *_state)
{


    dst->nvars = src->nvars;
    icopyallocv(src->nvars, &src->varidx, &dst->varidx, _state);
    rcopyallocv(src->nvars, &src->b, &dst->b, _state);
    dyncrscopy(&src->fullq, &dst->fullq, _state);
    dst->cl = src->cl;
    dst->cu = src->cu;
    dst->applyorigin = src->applyorigin;
}


/*************************************************************************
Copies quadratic constraint with insertion of variable VIdx into  position
InsertPos, with 0<=InsertPos<=NVars. Variables at position  InsertPos  and
past it are shifted to the right.

The function checks that Src.VarIdx[InsertPos-1]<VIdx<Src.VarIdx[InsertPos].

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqccopyinsertrowcol(dynamiccrsqconstraint* src,
     ae_int_t vidx,
     ae_int_t insertpos,
     dynamiccrsqconstraint* dst,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t offs;


    ae_assert(insertpos>=0&&insertpos<=src->nvars, "dynqcCopyInsertRowCol: incorrect InsertPos", _state);
    ae_assert(insertpos==0||src->varidx.ptr.p_int[insertpos-1]<vidx, "dynqcCopyInsertRowCol: VIdx is out of order (left)", _state);
    ae_assert(insertpos==src->nvars||src->varidx.ptr.p_int[insertpos]>vidx, "dynqcCopyInsertRowCol: VIdx is out of order (right)", _state);
    dst->nvars = src->nvars+1;
    dst->cl = src->cl;
    dst->cu = src->cu;
    dst->applyorigin = src->applyorigin;
    iallocv(dst->nvars, &dst->varidx, _state);
    rallocv(dst->nvars, &dst->b, _state);
    offs = 0;
    for(i=0; i<=src->nvars; i++)
    {
        if( i==insertpos )
        {
            dst->varidx.ptr.p_int[offs] = vidx;
            dst->b.ptr.p_double[offs] = 0.0;
            offs = offs+1;
        }
        if( i<src->nvars )
        {
            dst->varidx.ptr.p_int[offs] = src->varidx.ptr.p_int[i];
            dst->b.ptr.p_double[offs] = src->b.ptr.p_double[i];
            offs = offs+1;
        }
    }
    ae_assert(offs==dst->nvars, "PRESOLVER: integrity check 4228 failed", _state);
    dyncrscopyinsertrowcol(&src->fullq, insertpos, &dst->fullq, _state);
}


/*************************************************************************
Copies quadratic constraint with deletion of variable at position DeletePos,
with 0<=DeletePos<NVars. Variables at the position DeletePos and  past  it
are shifted to the left. If NVars=1, then an empty quadratic constraint is
correctly created.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqccopydeleterowcol(const dynamiccrsqconstraint* src,
     ae_int_t deletepos,
     dynamiccrsqconstraint* dst,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t offs;


    ae_assert(deletepos>=0&&deletepos<src->nvars, "dynqcCopyDeleteRowCol: incorrect DeletePos", _state);
    dst->nvars = src->nvars-1;
    dst->cl = src->cl;
    dst->cu = src->cu;
    dst->applyorigin = src->applyorigin;
    if( dst->nvars==0 )
    {
        dst->fullq.n = 0;
        dst->fullq.m = 0;
        return;
    }
    iallocv(dst->nvars, &dst->varidx, _state);
    rallocv(dst->nvars, &dst->b, _state);
    offs = 0;
    for(i=0; i<=src->nvars-1; i++)
    {
        if( i!=deletepos )
        {
            dst->varidx.ptr.p_int[offs] = src->varidx.ptr.p_int[i];
            dst->b.ptr.p_double[offs] = src->b.ptr.p_double[i];
            offs = offs+1;
        }
    }
    dyncrscopydeleterowcol(&src->fullq, deletepos, &dst->fullq, _state);
}


/*************************************************************************
Copies quadratic constraint with deletion of  variables  DeleteSet  and  a
corresponding shifts to the left in variables indexes.

If NVars=|DeleteSet|, then an empty quadratic constraint is correctly created.

Buf must be a preallocated array, with at least Src.NVars elements.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqccopydeleterowscols(const dynamiccrsqconstraint* src,
     const niset* deleteset,
     dynamiccrsqconstraint* dst,
     /* Integer */ ae_vector* buf,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t offs;


    ae_assert(buf->cnt>=src->nvars, "dynqcCopyDeleteRowsCols: buf is too short", _state);
    ae_assert(deleteset->nstored>=0&&deleteset->nstored<=src->nvars, "dynqcCopyDeleteRowsCols: incorrect DeletePos", _state);
    for(i=0; i<=deleteset->nstored-1; i++)
    {
        ae_assert(deleteset->items.ptr.p_int[i]>=0&&deleteset->items.ptr.p_int[i]<src->nvars, "dynqcCopyDeleteRowsCols: items in DeleteSet are outside of [0,NVars) range", _state);
    }
    dst->nvars = src->nvars-deleteset->nstored;
    dst->cl = src->cl;
    dst->cu = src->cu;
    dst->applyorigin = src->applyorigin;
    if( dst->nvars==0 )
    {
        dst->fullq.n = 0;
        dst->fullq.m = 0;
        return;
    }
    iallocv(dst->nvars, &dst->varidx, _state);
    rallocv(dst->nvars, &dst->b, _state);
    offs = 0;
    for(i=0; i<=src->nvars-1; i++)
    {
        if( deleteset->locationof.ptr.p_int[i]<0 )
        {
            dst->varidx.ptr.p_int[offs] = src->varidx.ptr.p_int[i];
            dst->b.ptr.p_double[offs] = src->b.ptr.p_double[i];
            offs = offs+1;
        }
    }
    dyncrscopydeleterowscols(&src->fullq, deleteset, &dst->fullq, buf, _state);
}


/*************************************************************************
Factors out variable K0 from a  quadratic  form  c'x + 0.5x'Hx by making a
substitution X[k0]:=alpha0 + alpha1*X[k1]  and  correspondingly  rewriting
c and H.

Returns constant term that is produced as a result of such a transformation.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static double lpqppresolve_factoroutfromquadratic(dynamiccrs* h,
     /* Real    */ ae_vector* c,
     ae_int_t k0,
     double alpha0,
     double alpha1,
     ae_int_t k1,
     ae_state *_state)
{
    double h00;
    double h11;
    double h01;
    double v;
    double v0;
    double v1;
    ae_int_t ii;
    ae_int_t j;
    double result;


    result = (double)(0);
    
    /*
     * Modify linear term with an update to C[K1] from C[K0]
     */
    c->ptr.p_double[k1] = c->ptr.p_double[k1]+c->ptr.p_double[k0]*alpha1;
    result = result+c->ptr.p_double[k0]*alpha0;
    c->ptr.p_double[k0] = (double)(0);
    
    /*
     * Handle updates coming from the quadratic term
     *
     * Analyze how 2x2 quadratic [h00 h01 ; h10 h11] changes when we
     * substitute x0 := alpha0 + alpha1*x1.
     *
     * We have
     *
     *     h00*(alpha0+alpha1*x1)^2 + 2*h01*(alpha0+alpha1*x1)*x1 + h11*x1^2 =
     *     h00*alpha0^2 + 2*h00*alpha0*alpha1*x1 + h00*alpha1^2*x1^2   +   2*h01*alpha0*x1+2*h01*alpha1*x1^2 + h11*x1^2 =
     *     h00*alpha0^2 + 2*(h00*alpha0*alpha1+h01*alpha0)*x1 + (h00*alpha1^2+2*h01*alpha1+h11)*x1^2
     */
    h00 = dyncrsgetexistingelement(h, k0, k0, _state);
    h11 = dyncrsgetexistingelement(h, k1, k1, _state);
    h01 = dyncrsgetelementifexists(h, k0, k1, _state);
    
    /*
     * Handle updates coming from modification of elements of H that are outside of the
     * [k0,k1]x[k0,k1] diagonal block. The constant term in X[K0]:=Alpha0+Alpha1*X[K1]
     * updates the linear term C[], the linear term Alpha1 updates the matrix H.
     *
     * The matrix H is updates applied to its column K1, then to its row K1. The row update
     * modifies the [k0,k1]x[k0,k1] diagonal block because there is no easy way to do it
     * without touching elements that we want to process later. We handle it by saving
     * H00, H01, H11 prior to this block and by discarding and rewriting diagonal completely
     * after calling DynCRSAddRowTo().
     */
    for(ii=h->rowbegin.ptr.p_int[k0]; ii<=h->rowend.ptr.p_int[k0]-1; ii++)
    {
        j = h->idx.ptr.p_int[ii];
        if( j!=k0&&j!=k1 )
        {
            
            /*
             * Update C[] and column K1 of H.
             */
            v = h->vals.ptr.p_double[ii];
            c->ptr.p_double[j] = c->ptr.p_double[j]+v*alpha0;
            dyncrsfactoroutfromrow(h, j, k0, 0.0, alpha1, k1, ae_false, &v0, &v1, _state);
        }
    }
    dyncrsaddrowto(h, k0, alpha1, k1, ae_true, ae_false, _state);
    dyncrsclearrow(h, k0, _state);
    dyncrsremovefromrow(h, k1, k0, _state);
    
    /*
     * Handle updates coming from substituting X[K0]:=Alpha0+Alpha1*X[K1] to the
     * [k0,k1]x[k0,k1] diagonal block.
     */
    result = result+0.5*h00*alpha0*alpha0;
    c->ptr.p_double[k1] = c->ptr.p_double[k1]+(h00*alpha0*alpha1+h01*alpha0);
    dyncrssetexistingelement(h, k1, k1, h00*alpha1*alpha1+(double)2*h01*alpha1+h11, _state);
    return result;
}


/*************************************************************************
Fixed single variable at the quadratic form c'x + 0.5x'Hx and correspondingly
rewrites c and H, clearing entries (but not removing them).

Returns constant term that is produced as a result of such a transformation.

  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static double lpqppresolve_fixquadraticvariable(dynamiccrs* h,
     /* Real    */ ae_vector* c,
     ae_int_t fixidx,
     double fixval,
     ae_state *_state)
{
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t j;
    ae_int_t n;
    double result;


    ae_assert(h->n==h->m, "PRESOLVER: integrity check 5812 failed", _state);
    ae_assert(fixidx>=0&&fixidx<h->n, "PRESOLVER: integrity check 5813 failed", _state);
    result = (double)(0);
    n = h->n;
    if( n==0 )
    {
        return result;
    }
    
    /*
     * Modify linear term
     */
    result = result+c->ptr.p_double[fixidx]*fixval;
    c->ptr.p_double[fixidx] = 0.0;
    
    /*
     * Modify quadratic term: scan FixIdx-th row, for each off-diagonal element found
     * clear (set to zero) corresponding element from FixIdx-th column
     */
    j0 = h->rowbegin.ptr.p_int[fixidx];
    j1 = h->rowend.ptr.p_int[fixidx]-1;
    for(jj=j0; jj<=j1; jj++)
    {
        j = h->idx.ptr.p_int[jj];
        if( j!=fixidx )
        {
            
            /*
             * Offdiagonal element
             */
            c->ptr.p_double[j] = c->ptr.p_double[j]+h->vals.ptr.p_double[jj]*fixval;
            h->vals.ptr.p_double[jj] = 0.0;
            h->vals.ptr.p_double[ibinarysearchexisting(&h->idx, h->rowbegin.ptr.p_int[j], h->rowend.ptr.p_int[j], fixidx, _state)] = 0.0;
        }
        else
        {
            
            /*
             * Diagonal element
             */
            result = result+0.5*h->vals.ptr.p_double[jj]*fixval*fixval;
            h->vals.ptr.p_double[jj] = 0.0;
        }
    }
    return result;
}


/*************************************************************************
convert single quadratic constraint between formats


  -- ALGLIB --
     Copyright 01.07.2024 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_dynqcpermtoxqc(dynamiccrsqconstraint* src,
     /* Integer */ const ae_vector* packxperm,
     /* Integer */ const ae_vector* unpackxperm,
     xquadraticconstraint* dst,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    ae_int_t jj;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t offs;
    ae_int_t nv;
    ae_int_t jprev;


    nv = src->nvars;
    dst->nvars = nv;
    dst->cl = src->cl;
    dst->cu = src->cu;
    dst->applyorigin = src->applyorigin;
    if( nv>0 )
    {
        iallocv(nv, &dst->varidx, _state);
        for(i=0; i<=nv-1; i++)
        {
            dst->varidx.ptr.p_int[i] = packxperm->ptr.p_int[src->varidx.ptr.p_int[i]];
        }
        for(i=0; i<=nv-2; i++)
        {
            ae_assert(dst->varidx.ptr.p_int[i]<dst->varidx.ptr.p_int[i+1], "PRESOLVER: integrity check 1658 failed", _state);
        }
        rcopyallocv(nv, &src->b, &dst->b, _state);
        dst->lowerq.matrixtype = 1;
        dst->lowerq.m = nv;
        dst->lowerq.n = nv;
        iallocv(nv, &dst->lowerq.didx, _state);
        iallocv(nv, &dst->lowerq.uidx, _state);
        iallocv(nv+1, &dst->lowerq.ridx, _state);
        dst->lowerq.ridx.ptr.p_int[0] = 0;
        for(i=0; i<=nv-1; i++)
        {
            offs = dst->lowerq.ridx.ptr.p_int[i];
            igrowv(offs+nv, &dst->lowerq.idx, _state);
            rgrowv(offs+nv, &dst->lowerq.vals, _state);
            jprev = -1;
            j0 = src->fullq.rowbegin.ptr.p_int[i];
            j1 = src->fullq.rowend.ptr.p_int[i]-1;
            for(jj=j0; jj<=j1; jj++)
            {
                j = src->fullq.idx.ptr.p_int[jj];
                if( j<=jprev )
                {
                    ae_assert(ae_false, "PRESOLVER: integrity check 381649 failed", _state);
                }
                jprev = j;
                if( j>i )
                {
                    continue;
                }
                dst->lowerq.idx.ptr.p_int[offs] = j;
                dst->lowerq.vals.ptr.p_double[offs] = src->fullq.vals.ptr.p_double[jj];
                offs = offs+1;
            }
            ae_assert(offs>dst->lowerq.ridx.ptr.p_int[i]&&dst->lowerq.idx.ptr.p_int[offs-1]==i, "PRESOLVER: integrity check 389651 failed", _state);
            dst->lowerq.didx.ptr.p_int[i] = offs-1;
            dst->lowerq.uidx.ptr.p_int[i] = offs;
            dst->lowerq.ridx.ptr.p_int[i+1] = offs;
        }
        dst->lowerq.ninitialized = dst->lowerq.ridx.ptr.p_int[nv];
    }
}


/*************************************************************************
Initialize presolver stack

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstackinit(ae_int_t n,
     ae_int_t m,
     ae_int_t mqc,
     ae_int_t mcc,
     presolverstack* s,
     ae_state *_state)
{


    s->n = n;
    s->m = m;
    s->mqc = mqc;
    s->mcc = mcc;
    s->ntrf = 0;
    isetallocv(1, 0, &s->idataridx, _state);
    isetallocv(1, 0, &s->rdataridx, _state);
}


/*************************************************************************
Streams boolean value to the presolver stack data storage (the data
are appended to the last transform on top of the stack).

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamb(presolverstack* s,
     ae_bool b,
     ae_state *_state)
{
    ae_int_t ilast;


    ilast = s->idataridx.ptr.p_int[s->ntrf];
    igrowv(ilast+1, &s->idata, _state);
    s->idata.ptr.p_int[ilast] = icase2(b, 1, 0, _state);
    s->idataridx.ptr.p_int[s->ntrf] = ilast+1;
}


/*************************************************************************
Streams integer value to the presolver stack data storage (the data
are appended to the last transform on top of the stack).

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreami(presolverstack* s,
     ae_int_t i,
     ae_state *_state)
{
    ae_int_t ilast;


    ilast = s->idataridx.ptr.p_int[s->ntrf];
    igrowv(ilast+1, &s->idata, _state);
    s->idata.ptr.p_int[ilast] = i;
    s->idataridx.ptr.p_int[s->ntrf] = ilast+1;
}


/*************************************************************************
Streams real value to the presolver stack data storage (the data
are appended to the last transform on top of the stack).

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamr(presolverstack* s,
     double v,
     ae_state *_state)
{
    ae_int_t rlast;


    rlast = s->rdataridx.ptr.p_int[s->ntrf];
    rgrowv(rlast+1, &s->rdata, _state);
    s->rdata.ptr.p_double[rlast] = v;
    s->rdataridx.ptr.p_int[s->ntrf] = rlast+1;
}


/*************************************************************************
Streams a integer/real pair to the presolver stack data storage (the data
are appended to the last transform on top of the stack).

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamir(presolverstack* s,
     ae_int_t i,
     double v,
     ae_state *_state)
{
    ae_int_t ilast;
    ae_int_t rlast;


    ilast = s->idataridx.ptr.p_int[s->ntrf];
    rlast = s->rdataridx.ptr.p_int[s->ntrf];
    igrowv(ilast+1, &s->idata, _state);
    rgrowv(rlast+1, &s->rdata, _state);
    s->idata.ptr.p_int[ilast] = i;
    s->rdata.ptr.p_double[rlast] = v;
    s->idataridx.ptr.p_int[s->ntrf] = ilast+1;
    s->rdataridx.ptr.p_int[s->ntrf] = rlast+1;
}


/*************************************************************************
Streams DynamicCRS row.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamcrsrow(presolverstack* s,
     const dynamiccrs* a,
     ae_int_t i,
     ae_state *_state)
{
    ae_int_t k;


    lpqppresolve_presolverstreami(s, a->rowend.ptr.p_int[i]-a->rowbegin.ptr.p_int[i], _state);
    for(k=a->rowbegin.ptr.p_int[i]; k<=a->rowend.ptr.p_int[i]-1; k++)
    {
        lpqppresolve_presolverstreamir(s, a->idx.ptr.p_int[k], a->vals.ptr.p_double[k], _state);
    }
}


/*************************************************************************
Streams DynamicCRS row, except for element in the column NotIdx (if such an
element is present)

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamcrsrownot1(presolverstack* s,
     const dynamiccrs* a,
     ae_int_t i,
     ae_int_t notidx,
     ae_state *_state)
{
    ae_int_t k;
    ae_int_t j0;
    ae_int_t j1;
    ae_int_t cnt;


    j0 = a->rowbegin.ptr.p_int[i];
    j1 = a->rowend.ptr.p_int[i]-1;
    cnt = 0;
    for(k=j0; k<=j1; k++)
    {
        if( a->idx.ptr.p_int[k]!=notidx )
        {
            cnt = cnt+1;
        }
    }
    lpqppresolve_presolverstreami(s, cnt, _state);
    for(k=j0; k<=j1; k++)
    {
        if( a->idx.ptr.p_int[k]!=notidx )
        {
            lpqppresolve_presolverstreamir(s, a->idx.ptr.p_int[k], a->vals.ptr.p_double[k], _state);
        }
    }
}


/*************************************************************************
Streams entries of a DynamicCRS row that have corresponding flags set to false.

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverstreamcrsrownonflagged(presolverstack* s,
     const dynamiccrs* a,
     ae_int_t i,
     /* Boolean */ const ae_vector* flags,
     ae_state *_state)
{
    ae_int_t k;
    ae_int_t cnt;
    ae_int_t j0;
    ae_int_t j1;


    j0 = a->rowbegin.ptr.p_int[i];
    j1 = a->rowend.ptr.p_int[i]-1;
    cnt = 0;
    for(k=j0; k<=j1; k++)
    {
        if( !flags->ptr.p_bool[a->idx.ptr.p_int[k]] )
        {
            cnt = cnt+1;
        }
    }
    lpqppresolve_presolverstreami(s, cnt, _state);
    for(k=j0; k<=j1; k++)
    {
        if( !flags->ptr.p_bool[a->idx.ptr.p_int[k]] )
        {
            lpqppresolve_presolverstreamir(s, a->idx.ptr.p_int[k], a->vals.ptr.p_double[k], _state);
        }
    }
}


/*************************************************************************
Select transformation TIdx as the source for stream reads

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverselectstreamsource(presolverstack* s,
     ae_int_t tidx,
     ae_state *_state)
{


    s->sourceidx = tidx;
    s->isrc = s->idataridx.ptr.p_int[tidx];
    s->rsrc = s->rdataridx.ptr.p_int[tidx];
}


/*************************************************************************
Reads from presolver stack boolean value, advances stream pointer

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverunstreamb(presolverstack* s,
     ae_bool* v,
     ae_state *_state)
{

    *v = ae_false;

    *v = s->idata.ptr.p_int[s->isrc]!=0;
    s->isrc = s->isrc+1;
}


/*************************************************************************
Reads from presolver stack boolean value, advances stream pointer.
Function instead of a proceduring

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static ae_bool lpqppresolve_presolverunstreambf(presolverstack* s,
     ae_state *_state)
{
    ae_bool result;


    result = s->idata.ptr.p_int[s->isrc]!=0;
    s->isrc = s->isrc+1;
    return result;
}


/*************************************************************************
Reads from presolver stack integer value, advances stream pointer

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverunstreami(presolverstack* s,
     ae_int_t* v,
     ae_state *_state)
{

    *v = 0;

    *v = s->idata.ptr.p_int[s->isrc];
    s->isrc = s->isrc+1;
}


/*************************************************************************
Reads from presolver stack real value, advances stream pointer

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverunstreamr(presolverstack* s,
     double* v,
     ae_state *_state)
{

    *v = 0.0;

    *v = s->rdata.ptr.p_double[s->rsrc];
    s->rsrc = s->rsrc+1;
}


/*************************************************************************
Reads from presolver stack int/real pair, advances stream pointers

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverunstreamir(presolverstack* s,
     ae_int_t* vi,
     double* vr,
     ae_state *_state)
{

    *vi = 0;
    *vr = 0.0;

    *vi = s->idata.ptr.p_int[s->isrc];
    s->isrc = s->isrc+1;
    *vr = s->rdata.ptr.p_double[s->rsrc];
    s->rsrc = s->rsrc+1;
}


/*************************************************************************
Reads from presolver stack compressed sparse vector, advances stream pointers

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverunstreamsparsevec(presolverstack* s,
     ae_int_t* cnt,
     /* Integer */ ae_vector* idx,
     /* Real    */ ae_vector* vals,
     ae_state *_state)
{
    ae_int_t i;
    ae_int_t j;
    double v;


    lpqppresolve_presolverunstreami(s, cnt, _state);
    iallocv(*cnt, idx, _state);
    rallocv(*cnt, vals, _state);
    for(i=0; i<=*cnt-1; i++)
    {
        lpqppresolve_presolverunstreamir(s, &j, &v, _state);
        idx->ptr.p_int[i] = j;
        vals->ptr.p_double[i] = v;
    }
}


/*************************************************************************
Checks that we are at the end of the stream corresponding to transfrom #TIdx

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverasserteos(presolverstack* s,
     ae_state *_state)
{


    ae_assert(s->isrc==s->idataridx.ptr.p_int[s->sourceidx+1], "PresolverAssertEOS: unread integers in the stream", _state);
    ae_assert(s->rsrc==s->rdataridx.ptr.p_int[s->sourceidx+1], "PresolverAssertEOS: unread reals in the stream", _state);
}


/*************************************************************************
Appends transform placeholder

  -- ALGLIB --
     Copyright 01.07.2022 by Bochkanov Sergey
*************************************************************************/
static void lpqppresolve_presolverappendtrf(presolverstack* s,
     ae_int_t tt,
     ae_state *_state)
{


    igrowv(s->ntrf+1, &s->trftype, _state);
    igrowv(s->ntrf+2, &s->idataridx, _state);
    igrowv(s->ntrf+2, &s->rdataridx, _state);
    s->trftype.ptr.p_int[s->ntrf] = tt;
    s->idataridx.ptr.p_int[s->ntrf+1] = s->idataridx.ptr.p_int[s->ntrf];
    s->rdataridx.ptr.p_int[s->ntrf+1] = s->rdataridx.ptr.p_int[s->ntrf];
    s->ntrf = s->ntrf+1;
}


